const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const plain=v=>typeof v==='string'?v:Array.isArray(v)?v.map(plain).join(' · '):v?Object.values(v).map(plain).join(' · '):'';
const arr=v=>Array.isArray(v)?v:v?[v]:[];const list=v=>`<ul>${arr(v).map(x=>`<li>${e(plain(x))}</li>`).join('')}</ul>`;
const normalize=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();const matches=(x,q)=>normalize(JSON.stringify(x)).includes(normalize(q));
const icons={playbook:'M5 3h14v18H5zM9 7h6M9 11h6M9 15l2 2 4-4',map:'M12 9V3M5 9H3v6h6V9H5M15 9h6v6h-6zM9 12h6M12 15v6M9 3h6M9 21h6',guided:'M3 3h18v13H3zM12 16v6M7 22l5-6 5 6M7 8h6M7 12h10',course:'M3 4h18v14H3zM7 22l5-4 5 4M7 8h10M7 12h6',videos:'M3 5h18v14H3zM10 9l5 3-5 3z',foundations:'M4 20V9l8-6 8 6v11M8 20v-7h8v7M3 20h18',ledger:'M4 4h16v16H4zM8 8h8M8 12h8M8 16h3',home:'M3 11 12 3l9 8M5 10v11h5v-7h4v7h5V10',atlas:'M4 4h6v6H4zM14 4h6v6h-6zM4 14h6v6H4zM14 14h6v6h-6z',questions:'M7 9a5 5 0 0 1 10 0c0 3-5 3-5 6M12 19h.01M4 3h16v19H4z',mocks:'M9 2h6M12 5v7l4 2M19 6l2-2M21 13a9 9 0 1 1-18 0 9 9 0 0 1 18 0',lab:'M9 3h6M10 3v7L4 20h16l-6-10V3M7 15h10',cases:'M3 7h18v14H3zM8 7V3h8v4M3 12h18M10 11v3h4v-3',people:'M16 21v-3c0-5-12-5-12 0v3M14 7a4 4 0 1 1-8 0 4 4 0 0 1 8 0M18 4a3 3 0 0 1 0 6M19 15c3 0 3 3 3 6',plan:'M4 4h16v17H4zM8 2v5M16 2v5M4 10h16M8 14h2M14 14h2M8 18h2',sources:'M3 4c4-1 6-1 9 1 3-2 5-2 9-1v16c-4-1-6-1-9 1-3-2-5-2-9-1zM12 5v16',arrow:'M5 12h14M14 7l5 5-5 5',layers:'m12 3 10 5-10 5L2 8zM2 12l10 5 10-5M2 16l10 5 10-5',check:'m5 12 4 4L19 6',code:'m8 6-6 6 6 6M16 6l6 6-6 6M14 3l-4 18'};
const icon=(n='layers')=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${(icons[n]||icons.layers).split('|').map(d=>`<path d="${d}"/>`).join('')}</svg>`;
const fmt=n=>new Intl.NumberFormat('pt-BR').format(n);const chip=(text,type='')=>`<span class="chip ${type}">${e(text)}</span>`;
const progressStore=createProgressStore({storage:{getItem:key=>localStorage.getItem(key),setItem:(key,value)=>localStorage.setItem(key,value)},onError:()=>toast('Não foi possível salvar no navegador. Exporte seu progresso antes de sair.')});
let progress=progressStore.load();
function save(){const persisted=progressStore.save(progress);if(persisted)progress=progressStore.snapshot();return persisted}
let cloud='aws', diagramModel=null;
let D={architectures:[],technologies:[],questions:[],mocks:[],sources:[],research:{}}, sourceMap={}, filter={q:'',category:'',level:'',priority:'',saved:false,page:1}, currentRoute='', currentId='', tab='overview', compare=[], timer={id:null,elapsed:0,running:false,start:0}, activeFlash=0;
let resumePlace=null,requestedResumeY=null,activeHash='',resumeDebounce;
try{const v=JSON.parse(localStorage.getItem('nuarch-last-place')||'null');if(v&&typeof v.hash==='string'&&/^#[a-z][a-z0-9-/]*(\?.*)?$/.test(v.hash)&&typeof v.title==='string'&&Number.isFinite(v.y))resumePlace=v;}catch{}
const mindMap=createMindMap({escape:e,sources:refs,readNote:id=>progress.notes[`map:${id}`]||'',writeNote:(id,value)=>{progress.notes[`map:${id}`]=value;save()},isRead:id=>progress.checks.includes(`map:${id}`),toggleRead:id=>toggle(progress.checks,`map:${id}`),onSelect:id=>{currentId=id;activeHash=location.hash;rememberPlace();document.title=`${D.mindmap.nodes.find(n=>n.id===id)?.label||D.mindmap.groups.find(g=>g.id===id)?.label||'Mapa mental'} · nuArch`}});
const playbook=createPlaybook({escape:e,sources:refs,architectures:()=>D.architectures,mindmap:()=>D.mindmap,technologies:()=>D.technologies,readNote:key=>progress.notes[key]||'',writeNote:(key,value)=>{progress.notes[key]=value;save()},isDone:key=>progress.checks.includes(key),toggleDone:key=>toggle(progress.checks,key),onNavigate:(id,name)=>{currentId=id;activeHash=location.hash;rememberPlace();document.title=`${name} · Roteiro do dia · nuArch`}});
function rememberPlace(){if(!activeHash||!currentRoute||currentRoute==='home')return;const name=currentRoute==='map'?(D.mindmap?.nodes.find(n=>n.id===currentId)?.label||D.mindmap?.groups.find(g=>g.id===currentId)?.label||'Mapa mental'):currentRoute==='playbook'?(D.playbook?.cases.find(c=>c.id===currentId)?.title||'Roteiro do dia'):currentRoute==='guided'?(D.guided?.cases.find(c=>c.id===currentId)?.title||'Entrevistas guiadas'):$('#main h1')?.textContent;resumePlace={hash:activeHash,title:name||nav.find(x=>x[0]===currentRoute)?.[1]||'Seu estudo',y:Math.max(0,Math.round(scrollY))};try{localStorage.setItem('nuarch-last-place',JSON.stringify(resumePlace))}catch{}}
function enhanceReading(){const main=$('#main');main.dataset.route=currentRoute;const headings=$$('h2',main).filter(h=>!h.closest('.guided-transcript,.map-page')&&h.textContent.trim());if(!['home','map','playbook'].includes(currentRoute)&&headings.length>=3){const navEl=document.createElement('nav');navEl.className='page-outline';navEl.setAttribute('aria-label','Índice da página');navEl.innerHTML=`<label>Nesta página<select id="page-outline-select"><option value="">Escolha uma seção…</option>${headings.map((h,i)=>`<option value="${i}">${e(h.textContent)}</option>`).join('')}</select></label><button id="back-top">↑ Início</button>`;main.prepend(navEl);$('#page-outline-select').onchange=ev=>{if(ev.target.value==='')return;const h=headings[Number(ev.target.value)];let p=h.parentElement;while(p&&p!==main){if(p.tagName==='DETAILS')p.open=true;p=p.parentElement;}h.tabIndex=-1;h.classList.add('outline-target');h.scrollIntoView({block:'start'});h.focus({preventScroll:true});};$('#back-top').onclick=()=>{scrollTo({top:0,behavior:'auto'});main.focus({preventScroll:true})};}if(currentRoute!=='map'&&currentRoute!=='home'&&currentId){const related=D.mindmap.nodes.filter(n=>n.links.some(l=>l.href.split('?')[0]===`#${currentRoute}/${currentId}`)).slice(0,4);if(related.length){const context=document.createElement('div');context.className='map-context-bar';context.innerHTML=`<span>Relacione no mapa</span>${related.map(n=>`<a href="#map/${e(n.id)}">${e(n.label)} ↗</a>`).join('')}`;main.prepend(context);}}document.title=`${currentRoute==='map'?(D.mindmap.nodes.find(n=>n.id===currentId)?.label||'Mapa mental'):main.querySelector('h1')?.innerText.replace(/\s+/g,' ')||'Architecture Lab'} · nuArch`;$$('[data-resume]',main).forEach(a=>a.onclick=()=>{requestedResumeY=resumePlace?.y||0});}
window.addEventListener('scroll',()=>{clearTimeout(resumeDebounce);resumeDebounce=setTimeout(rememberPlace,450)},{passive:true});window.addEventListener('pagehide',rememberPlace);
const navGroups=[
  {label:'Orientação',description:'Encontre seu ponto de partida e o que priorizar.',items:[['home','Início'],['map','Mapa mental'],['plan','Plano de estudo'],['people','Contexto da entrevista']]},
  {label:'Entender',description:'Conecte conceitos, mecanismos e escolhas de arquitetura.',items:[['foundations','Fundamentos distribuídos'],['atlas','Atlas de arquiteturas'],['ledger','Ledger bancário']]},
  {label:'Praticar',description:'Transforme leitura em decisões e explicações em voz alta.',items:[['playbook','Roteiro do dia'],['guided','Entrevistas guiadas'],['mocks','Simulados de 60 min'],['questions','Perguntas & revisão'],['lab','Laboratório']]},
  {label:'Aprofundar',description:'Aprenda com casos, aulas e fontes para cada tema.',items:[['cases','Nubank na prática'],['videos','Videoteca'],['course','Curso LINUXtips'],['sources','Biblioteca & fontes']]}
];
const nav=navGroups.flatMap(g=>g.items);
function navRender(){ $('#nav').innerHTML=navGroups.map(g=>`<section class="nav-group"><h2>${g.label}</h2>${g.items.map(([id,name])=>`<a href="#${id}" class="nav-item ${currentRoute===id?'active':''}" ${currentRoute===id?'aria-current="page"':''}>${icon(id)}<span>${name}</span>${id==='questions'?`<span class="nav-count">${fmt(D.questions.length)}</span>`:id==='mocks'?`<span class="nav-count">${D.mocks.length}</span>`:''}</a>`).join('')}</section>`).join('');$('#crumb').textContent=nav.find(x=>x[0]===currentRoute)?.[1]||'Comparar';$('#section-crumb').textContent=navGroups.find(g=>g.items.some(x=>x[0]===currentRoute))?.label||'Entender';}

function refs(ids){return `<div class="source-links">${arr(ids).map(id=>sourceMap[id]).filter(Boolean).map(s=>s.url?`<a href="${e(s.url)}" target="_blank" rel="noopener">↗ ${e(s.title)}</a>`:`<a href="#sources">${e(s.title)} · material fornecido</a>`).join('')}</div>`}
function title(eyebrow,h,p,action=''){return `<div class="page-title"><div><div class="eyebrow"><span class="dot"></span>${e(eyebrow)}</div><h1>${e(h)}</h1><p>${e(p)}</p></div>${action}</div>`}
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),3000)}
function paginate(items,render,size=18){const pages=Math.ceil(items.length/size)||1;filter.page=Math.min(filter.page,pages);return `${items.length?items.slice((filter.page-1)*size,filter.page*size).map(render).join(''):'<div class="empty">Nenhum resultado. Experimente outro filtro.</div>'}${pages>1?`<div class="pagination"><button data-page="${filter.page-1}" ${filter.page===1?'disabled':''}>← Anterior</button><span>${filter.page} / ${pages}</span><button data-page="${filter.page+1}" ${filter.page===pages?'disabled':''}>Próxima →</button></div>`:''}`}
function options(items,selected,label){return `<option value="">${label}</option>${[...new Set(items.filter(Boolean))].sort().map(x=>`<option value="${e(x)}" ${selected===x?'selected':''}>${e(x)}</option>`).join('')}`}
function filters(items,placeholder,extra=''){return `<div class="filters"><input type="search" id="filter-q" placeholder="${e(placeholder)}" aria-label="Pesquisar conteúdo" value="${e(filter.q)}"><select id="filter-category" aria-label="Filtrar categoria">${options(items.map(x=>x.category||x.domain),filter.category,'Todas as categorias')}</select><select id="filter-level" aria-label="Filtrar nível">${options(items.map(x=>x.level),filter.level,'Todos os níveis')}</select>${items.some(x=>x.priority)?`<select id="filter-priority" aria-label="Filtrar prioridade">${options(items.map(x=>String(x.priority)),filter.priority,'Todas as prioridades')}</select>`:''}${extra}</div>`}
function filtered(items){return items.filter(x=>(!filter.q||matches(x,filter.q))&&(!filter.category||(x.category||x.domain)===filter.category)&&(!filter.level||x.level===filter.level)&&(!filter.priority||String(x.priority)===filter.priority))}
function heroArt(){return `<div class="hero-art" aria-label="Ilustração de uma arquitetura conectando API, eventos e dados"><svg viewBox="0 0 450 330" role="img"><defs><linearGradient id="glass" x1="0" y1="0" x2="1" y2="1"><stop stop-color="#fff" stop-opacity=".96"/><stop offset="1" stop-color="#e4c8fc" stop-opacity=".7"/></linearGradient><linearGradient id="purple" x1="0" x2="1" y1="0" y2="1"><stop stop-color="#aa53ee"/><stop offset="1" stop-color="#7020c7"/></linearGradient><filter id="drop"><feDropShadow dx="0" dy="12" stdDeviation="13" flood-color="#742ebd" flood-opacity=".13"/></filter></defs><ellipse cx="233" cy="272" rx="171" ry="43" fill="#d3b4f3" opacity=".15"/><path d="M84 132 220 192 374 127M220 192v69M223 99 84 162M223 99l151 58" stroke="#c6a3e5" stroke-width="1.5" fill="none" stroke-dasharray="5 6"/><g class="float-node" filter="url(#drop)"><path d="m145 113 82-42 85 42-85 44z" fill="#f7efff" stroke="#fff" stroke-width="2"/><path d="m145 113 82 44v60l-82-43z" fill="#dab9f5" stroke="#eee0fb"/><path d="m227 157 85-44v60l-85 44z" fill="url(#purple)"/><path d="m165 101 62-32 64 32-64 33z" fill="url(#glass)" stroke="#fff"/><path d="m181 96 45-22 45 22-45 23z" fill="url(#purple)" opacity=".8"/><g stroke="#fff" stroke-width="3" fill="none"><path d="m207 92 18 9 20-10M207 99l18 9 20-10"/></g><text x="183" y="163" transform="rotate(28 183 163)" fill="#8650b0" font-size="11" font-family="Manrope">SYSTEM</text></g><g class="float-node second" filter="url(#drop)"><rect x="24" y="92" width="102" height="67" rx="13" fill="url(#glass)" stroke="white" stroke-width="1.5"/><circle cx="46" cy="114" r="5" fill="#b574e7"/><text x="59" y="118" fill="#6a467f" font-size="10" font-weight="600">API Gateway</text><rect x="40" y="130" width="65" height="3" rx="2" fill="#c6a3e7"/><rect x="40" y="139" width="43" height="3" rx="2" fill="#ddc9ef"/></g><g class="float-node" filter="url(#drop)"><rect x="309" y="91" width="105" height="69" rx="13" fill="url(#glass)" stroke="white" stroke-width="1.5"/><path d="M325 108h13m-10 5h13m-16 5h13" stroke="#ad69e1" stroke-width="2"/><text x="347" y="116" fill="#6a467f" font-size="10" font-weight="600">Eventos</text><rect x="325" y="131" width="70" height="3" rx="2" fill="#c6a3e7"/><rect x="325" y="141" width="50" height="3" rx="2" fill="#ddc9ef"/></g><g class="float-node second" filter="url(#drop)"><rect x="177" y="244" width="105" height="56" rx="13" fill="url(#glass)" stroke="white" stroke-width="1.5"/><ellipse cx="199" cy="262" rx="8" ry="4" fill="none" stroke="#ac65e1" stroke-width="1.5"/><path d="M191 262v11c0 6 16 6 16 0v-11M191 268c0 6 16 6 16 0" fill="none" stroke="#ac65e1" stroke-width="1.5"/><text x="218" y="273" fill="#6a467f" font-size="10" font-weight="600">Ledger</text></g><circle class="packet" r="3" fill="#ad68e1"><animateMotion dur="5s" repeatCount="indefinite" path="M84 132 220 192 374 127"/></circle><circle cx="370" cy="221" r="4" fill="#c19be6"/><circle cx="110" cy="233" r="3" fill="#c19be6"/><path d="M337 44v9m-4-4h8M81 221v8m-4-4h8" stroke="#c6a5e4" stroke-width="1.5"/></svg></div>`}
function home(){const descriptions={playbook:`10 etapas adaptadas a ${D.playbook.cases.length} cenários, com fala, desenho e decisões a cada passo.`,map:'Seu draw.io em um mapa de conceitos, conexões e material de origem.',plan:'Prioridades e sessões para organizar o tempo de preparação.',people:'Formato, sinais de avaliação e contexto profissional público.',foundations:'Consistência, bancos, caches, tráfego e processamento assíncrono.',atlas:'64 padrões com mecanismos, falhas e opções de implementação.',ledger:'Partidas dobradas, imutabilidade, engine e recuperação.',guided:'5 conversas completas com fala e desenho evoluindo juntos.',mocks:'120 roteiros para ensaiar desenho, incidentes e evolução.',questions:'1.200 perguntas comentadas para testar o raciocínio.',lab:'Experimentos interativos com garantias e limites.',cases:'Casos de engenharia e relatos com origem identificada.',videos:'50 vídeos com perguntas de estudo e notas.',course:'29 aulas, 26 cases e 341 arquivos do curso LINUXtips.',sources:'Documentação e publicações para conferir e aprofundar.'};return `<section class="study-hero"><div><span class="eyebrow">NUARCH · SEU ESPAÇO DE ESTUDO</span><h1>Entenda as peças.<br><span class="gradient-text">Conecte as decisões.</span></h1><p>Do mapa mental à conversa de arquitetura. Explore o mecanismo, compare os custos e treine a explicação que sustenta sua escolha.</p><div class="actions"><a class="button primary" href="#map">Explorar meu mapa mental ↗</a><a class="button" href="#playbook">Preparar meu roteiro do dia →</a></div></div>${heroArt()}</section>${resumePlace?.hash?`<section class="resume-card"><div><span class="eyebrow">CONTINUE DE ONDE PAROU</span><h2>${e(resumePlace.title)}</h2><p>Seu ponto de leitura está salvo neste navegador.</p></div><a class="button primary" href="${e(resumePlace.hash)}" data-resume>Retomar estudo →</a></section>`:`<section class="resume-card"><div><span class="eyebrow">UM CAMINHO PARA COMEÇAR</span><h2>Escolha um problema. Siga suas consequências.</h2><p>Comece pelo mapa para situar os conceitos. Depois abra um mecanismo e use uma entrevista guiada para colocá-lo à prova.</p></div><a class="button" href="#plan">Organizar meu estudo →</a></section>`}<div class="stats">${[[D.mindmap.nodes.length,'Conceitos no seu mapa','map'],[D.architectures.length,'Padrões de arquitetura','atlas'],[D.questions.length,'Perguntas comentadas','questions'],[D.mocks.length,'Simulados de 60 min','mocks']].map(([n,t,i])=>`<div class="stat"><div class="stat-icon">${icon(i)}</div><div><strong>${fmt(n)}</strong><span>${t}</span></div></div>`).join('')}</div><div class="study-paths">${[['01','Encontre as conexões','Abra um tema do seu mural e acompanhe como rede, dados e falhas se influenciam.','map','Explorar o mapa'],['02','Aprofunde uma decisão','Localize a garantia, o gargalo, a alternativa e a condição que faria você mudar de ideia.','atlas','Estudar arquiteturas'],['03','Explique e adapte','Conduza uma entrevista em voz alta, desenhe por etapa e responda às mudanças de cenário.','playbook','Praticar com roteiro']].map(([i,h,p,r,l])=>`<article class="study-path"><span class="step-number">${i}</span><h2>${h}</h2><p>${p}</p><a href="#${r}">${l} →</a></article>`).join('')}</div><div class="section-heading"><h2>Todo o acervo, por objetivo</h2></div><div class="library-groups">${navGroups.map(g=>`<section><h2>${g.label}</h2><p>${g.description}</p><ul>${g.items.filter(([id])=>id!=='home').map(([id,t])=>`<li><a href="#${id}">${icon(id)}<span><strong>${t}</strong><small>${descriptions[id]}</small></span></a></li>`).join('')}</ul></section>`).join('')}</div><section class="panel home-progress"><h2>Seu progresso de estudo</h2><p>${progress.read.length} padrões estudados · ${progress.known.length} perguntas dominadas · ${progress.checks.filter(k=>k.startsWith('guided:')).length} etapas guiadas praticadas · ${progress.checks.filter(k=>k.startsWith('map:')).length} conceitos do mapa revisados.</p><p>Marque o que consegue explicar, retorne às lacunas e exporte o progresso pelo menu. Relatos, fontes oficiais e exercícios autorais têm origem identificada no material.</p></section>`}

function archCard(a){return `<article class="card"><div class="card-top"><span class="card-icon">${icon('layers')}</span>${chip(a.level)}</div><h3><a href="#atlas/${e(a.id)}">${e(a.title)}</a></h3><p>${e(a.summary)}</p><div class="card-bottom"><span>${e(a.category)}</span><a class="button small" href="#atlas/${e(a.id)}">Explorar ↗</a></div></article>`}
function atlas(){const items=filtered(D.architectures);return `${title('Mapeie o espaço de decisões','Atlas de arquiteturas','Estilos, padrões de integração, armazenamento e operação. Cada ficha conecta problema, mecanismo, custo e falha.',`<a class="button" href="#compare">Comparar padrões ⇄</a>`)}${filters(D.architectures,'Buscar padrão, tecnologia ou problema…')}<div class="result-line"><span>${items.length} padrões encontrados</span><span>${progress.read.length} estudados</span></div><div class="cards">${paginate(items,archCard,18)}</div>`}
function diagram(a){diagramModel=a;const nodes=a.nodes||[],edges=a.edges||[];const maxX=Math.max(800,...nodes.map(n=>n.x+85)),maxY=Math.max(360,...nodes.map(n=>n.y+45));return `<div class="diagram-controls"><span>Selecione uma peça para entender sua responsabilidade</span><button class="button small" id="animate-toggle">Pausar fluxo</button></div><div class="diagram" id="diagram"><svg viewBox="0 0 ${maxX} ${maxY}" role="group" aria-label="Diagrama interativo: ${e(a.title)}"><defs><marker id="arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 7 3.5 0 7" fill="#b99bda"/></marker></defs>${edges.map((l,i)=>{const f=nodes.find(n=>n.id===l.from),t=nodes.find(n=>n.id===l.to);if(!f||!t)return '';const dx=t.x-f.x,dy=t.y-f.y;let x1=f.x,y1=f.y,x2=t.x,y2=t.y;if(Math.abs(dx)>Math.abs(dy)){x1+=Math.sign(dx)*76;x2-=Math.sign(dx)*81}else{y1+=Math.sign(dy)*28;y2-=Math.sign(dy)*33}const path=`M${x1} ${y1} L${x2} ${y2}`;return `<path class="edge" d="${path}" marker-end="url(#arrow)"/><text class="edge-label" x="${(x1+x2)/2}" y="${(y1+y2)/2-10}" text-anchor="middle">${e(l.label)}</text><circle class="packet" r="3"><animateMotion dur="${2.8+i*.4}s" repeatCount="indefinite" path="${path}"/></circle>`}).join('')}${nodes.map(n=>{const tech=D.technologies.find(t=>t.id===n.tech||normalize(t.name)===normalize(n.tech||''));const logo=n.logoOverride||tech?.logo;const label=String(n.label);const maxChars=logo?17:24;const words=label.split(' ').flatMap(w=>w.length>maxChars?w.match(new RegExp('.{1,'+maxChars+'}','g')):[w]);let lines=[''];for(const word of words){const last=lines.length-1;if(lines[last]&&lines[last].length+word.length+1>maxChars)lines.push(word);else lines[last]+=(lines[last]?' ':'')+word}if(lines.length>3)lines=[...lines.slice(0,2),lines.slice(2).join(' ').slice(0,maxChars-1)+'…'];return `<g class="node" data-node="${e(n.id)}" tabindex="0" role="button" aria-label="${e(n.label)}"><rect x="${n.x-76}" y="${n.y-28}" width="152" height="56" rx="12"/>${logo?`<image href="${e(logo)}" x="${n.x-62}" y="${n.y-10}" width="20" height="20"/>`:''}${lines.map((line,i)=>`<text x="${n.x+(logo?14:0)}" y="${n.y-((lines.length-1)*7)+4+i*14}" text-anchor="middle" style="font-size:${logo?10:11}px">${e(line)}</text>`).join('')}</g>`}).join('')}</svg></div><div class="node-detail" id="node-detail"><strong>O que atravessa cada fronteira?</strong> Clique nos componentes para inspecionar fluxo, estado e responsabilidade. As animações são didáticas, sem simulação de rede real.</div>`}
function archDetail(id){const a=D.architectures.find(x=>x.id===id);if(!a)return notFound();const known=progress.read.includes(id);return `<a class="back" href="#atlas">← Voltar ao atlas</a><div class="detail-header"><div class="actions">${chip(a.category)}${chip(a.level,'neutral')}${chip(`Prioridade ${a.priority}`,'green')}</div><h1>${e(a.title)}</h1><p>${e(a.summary)}</p><div class="actions"><button class="button small" data-read="${e(id)}">${known?'✓ Estudado':'Marcar como estudado'}</button><a class="button small" href="#compare/${e(id)}">Comparar com outro padrão ⇄</a><a class="button small" href="#questions?q=${encodeURIComponent(a.title.includes('Outbox')?'outbox':a.title.split(' ')[0])}">Praticar perguntas ↗</a></div></div><div class="tabs" role="tablist">${[['overview','Desenho & fluxo'],['decisions','Trade-offs & falhas'],['internals','Por dentro'],['code','Código & invariantes'],['operations','Escala, falhas & SLA'],['deployments','AWS · Azure · On-prem']].map(([k,l])=>`<button class="tab ${tab===k?'active':''}" data-tab="${k}" role="tab" aria-selected="${tab===k}">${l}</button>`).join('')}</div><div class="reading">${tab==='overview'?`<section class="panel"><h2>Qual problema resolve?</h2><p>${e(a.problem)}</p>${diagram(a)}</section><div class="detail-grid"><section class="panel"><h2>O caminho de uma operação</h2>${arr(a.steps).map((s,i)=>`<h3>${String(i+1).padStart(2,'0')} · ${e(s.title)}</h3><p>${e(s.body)}</p>`).join('')}</section><div><section class="panel"><h3>Quando faz sentido</h3>${list(a.when)}<h3>Quando evitar</h3>${list(a.avoid)}</section><section class="panel"><span class="fact-label">Aplicação ao domínio financeiro</span><h3 style="margin-top:10px">${e(a.nubank?.scenario||'Cenário de treino')}</h3><p>${e(a.nubank?.evidence)}</p>${refs(a.nubank?.sourceIds)}</section></div></div>`:tab==='decisions'?`<section class="panel"><h2>A decisão e seu preço</h2><div class="table-wrap"><table><thead><tr><th>Escolha</th><th>Ganho</th><th>Custo</th></tr></thead><tbody>${arr(a.tradeoffs).map(t=>`<tr><td>${e(t.choice)}</td><td>${e(t.gain)}</td><td>${e(t.cost)}</td></tr>`).join('')}</tbody></table></div></section><div class="two-col"><section class="panel"><h2>Alternativas e substituições</h2>${arr(a.alternatives).map(t=>`<h3>${e(t.name)}</h3><p>${e(t.when)}</p>`).join('')}</section><section class="panel"><h2>Como falha</h2>${arr(a.failureModes).map(t=>`<h3>${e(t.failure)}</h3><p>${e(t.mitigation)}</p>`).join('')}</section></div>`:tab==='internals'?`<div class="two-col">${Object.entries(a.internals||{}).map(([k,v])=>`<section class="panel"><span class="eyebrow">${e({algorithm:'Mecanismo & algoritmo',complexity:'Custo computacional',hardware:'CPU, memória & armazenamento',latency:'Latência & caminho crítico',idempotency:'Duplicação & concorrência'}[k]||k)}</span><p>${e(plain(v))}</p></section>`).join('')}</div><div class="note">Complexidade assintótica não prevê p99. Meça distribuição, contenção, I/O, tamanhos e concorrência. Nenhuma latência aqui é um benchmark do Nubank.</div>`:tab==='operations'?operationsView(a):tab==='deployments'?deploymentView(a):`<section class="panel"><div class="panel-heading"><h2>Mecanismo em código</h2>${chip(a.code?.language||'Pseudocódigo')}</div><p>${e(a.code?.explanation)}</p><pre><code>${e(a.code?.text)}</code></pre><div class="note">Exemplo didático. Verifique limites transacionais, autorização, observabilidade e tratamento de falhas antes de adaptar a produção.</div></section><section class="panel"><h2>Defenda sem decorar</h2>${list(a.questions)}</section>`}<section class="panel"><h3>Continue nas fontes</h3>${refs(a.sourceIds)}</section></div>`}
function comparePage(id){if(id&&!compare.length)compare=[id];if(!compare.length&&D.architectures[0])compare=[D.architectures[0].id,D.architectures[1]?.id];return `${title('Decisões lado a lado','Compare antes de escolher','Compare requisitos, garantias, operação e custo. Alguns padrões são complementares, não substitutos.')}<div class="compare-grid">${[0,1].map(i=>{const a=D.architectures.find(x=>x.id===compare[i])||D.architectures[i];return `<section class="panel reading"><select data-compare="${i}" aria-label="Padrão ${i+1}" style="width:100%">${D.architectures.map(x=>`<option value="${e(x.id)}" ${x.id===a.id?'selected':''}>${e(x.title)}</option>`).join('')}</select><h2 style="margin-top:25px">${e(a.title)}</h2><p>${e(a.problem)}</p><h3>Escolha quando</h3>${list(a.when)}<h3>Evite quando</h3>${list(a.avoid)}<h3>Latência</h3><p>${e(a.internals?.latency)}</p><h3>Idempotência</h3><p>${e(a.internals?.idempotency)}</p><h3>Custos que você aceita</h3>${list(arr(a.tradeoffs).map(x=>`${x.choice}: ${x.cost}`))}<h3>O que pode substituí-lo</h3>${list(arr(a.alternatives).map(x=>`${x.name}: ${x.when}`))}<a class="button" href="#atlas/${e(a.id)}">Abrir ficha completa ↗</a></section>`}).join('')}</div>`}
function questionCard(q){return `<details class="question ${progress.known.includes(q.id)?'mastered':''}" id="${e(q.id)}" ${currentId===q.id?'open':''}><summary><span class="q-number">${e(q.id.replace(/[^\d]/g,''))}</span><div><div class="q-title">${e(q.question)}</div><div class="q-meta">${chip(q.category,'neutral')}${chip(q.level)}${progress.bookmarks.includes(q.id)?chip('Salva','green'):''}</div></div></summary><div class="question-body"><p><strong>Cenário:</strong> ${e(q.scenario)}</p><h4>O que uma boa resposta precisa demonstrar</h4>${list(q.answer)}<h4>Armadilhas de raciocínio</h4>${list(q.redFlags)}<h4>Aprofundamento</h4><p>${e(q.followUp)}</p>${refs(q.sourceIds)}<div class="actions"><button class="button small" data-known="${e(q.id)}">${progress.known.includes(q.id)?'✓ Dominada':'Já consigo explicar'}</button><button class="button small" data-bookmark="${e(q.id)}">${progress.bookmarks.includes(q.id)?'★ Salva':'☆ Revisar depois'}</button></div></div></details>`}
function questions(){let items=filtered(currentId?D.questions.filter(q=>q.id===currentId):D.questions).filter(q=>!filter.saved||progress.bookmarks.includes(q.id));return `${currentId?'<a class="back" href="#questions">← Todas as perguntas</a>':''}${title('Prática deliberada','Uma pergunta. Muitas decisões.',`${fmt(D.questions.length)} perguntas autorais com mecanismos, contrapontos e aprofundamentos. Não são perguntas atribuídas aos entrevistadores.`,`<a class="button" href="#flashcards">Modo flashcard ↗</a>`)}<div class="note"><strong>Como o banco foi construído:</strong> 60 cenários concretos × 20 lentes técnicas, de requisitos e concorrência a segurança e infraestrutura. As respostas são guias de raciocínio, não uma única solução correta.</div>${filters(D.questions,'Busque por cenário, mecanismo ou falha…',`<button class="button small" id="only-saved">${filter.saved?'★ Só salvas':'☆ Salvas'}</button>`)}<div class="result-line"><span>${fmt(items.length)} perguntas · tente responder antes de revelar</span><span>${progress.known.length} dominadas</span></div><div class="questions">${paginate(items,questionCard,20)}</div>`}
function flashcards(){const pool=D.questions.filter(q=>!progress.known.includes(q.id));const q=pool[activeFlash%Math.max(1,pool.length)];if(!q)return `${title('Revisão','Você revisou todo o banco','Use os simulados para testar integração e profundidade.')}<a class="button" href="#mocks">Abrir simulados</a>`;return `<a class="back" href="#questions">← Banco de perguntas</a>${title('Recuperação ativa','Explique antes de revelar',`${pool.length} perguntas ainda não marcadas como dominadas.`)}<section class="panel flashcard"><div>${chip(q.category)} ${chip(q.level,'neutral')}</div><h2 style="margin-top:25px">${e(q.question)}</h2><p>${e(q.scenario)}</p><div class="actions" style="justify-content:center"><button class="button primary" id="reveal-flash">Revelar critérios</button><button class="button" id="next-flash">Outra pergunta →</button></div><div id="flash-answer" class="hidden reading"><h3 style="margin-top:30px">Uma resposta defensável</h3>${list(q.answer)}<div class="note">${e(q.followUp)}</div><button class="button" data-flash-known="${e(q.id)}">✓ Consegui explicar sem consultar</button></div></section>`}
function mockCard(m){return `<article class="card"><div class="card-top">${chip(m.domain)}${chip(m.level,'neutral')}</div><h3><a href="#mocks/${e(m.id)}">${e(m.title)}</a></h3><p>${e(m.brief)}</p><div class="card-bottom"><span>◷ 60 min · ${m.timeline.length} etapas</span><a href="#mocks/${e(m.id)}" class="button small">Iniciar ↗</a></div></article>`}
function mocks(){return `${title('Da teoria à conversa','Seu próximo simulado começa aqui',`${D.mocks.length} roteiros autorais: 60 cenários em dois modos, desenho inicial e incidente/evolução. Use um quadro branco e pense em voz alta.`)}<section class="panel guided-home"><div><span class="eyebrow">NOVO · CINCO ENTREVISTAS GUIADAS</span><h2>Veja como a conversa vira arquitetura.</h2><p>Falas em primeira pessoa, desenho por etapa, interrupções e aprofundamentos Staff/Principal.</p></div><a class="button primary" href="#guided">Abrir entrevistas guiadas ↗</a></section>${filters(D.mocks,'Buscar domínio ou desafio…')}<div class="note"><strong>Como usar:</strong> leia o briefing, inicie o relógio e mantenha as respostas esperadas fechadas. Uma pessoa parceira pode conduzir os aprofundamentos. O portal não grava áudio nem avalia sua fala automaticamente.</div><div class="cards">${paginate(filtered(D.mocks),mockCard,12)}</div>`}
function elapsed(){return timer.elapsed+(timer.running?(Date.now()-timer.start)/1000:0)}
function timerHtml(){return `<section class="timer-shell"><div><span class="timer-label">TEMPO RESTANTE</span><strong class="timer-number" id="clock">60:00</strong></div><div class="progress-track"><div class="progress-fill" id="timer-fill"></div></div><div class="actions"><button class="button primary" id="timer-toggle">${timer.running?'Pausar':'Iniciar sessão'}</button><button class="button" id="timer-reset">Reiniciar</button></div></section>`}
function mockDetail(id){const m=D.mocks.find(x=>x.id===id);if(!m)return notFound();if(timer.id!==id)timer={id,elapsed:0,running:false,start:0};return `<a class="back" href="#mocks">← Todos os simulados</a>${title('Sessão de 60 minutos',m.title,m.brief)}<div class="two-col reading"><section class="panel"><h3>Requisitos a esclarecer</h3>${list(m.requirements)}</section><section class="panel"><h3>Restrições deste exercício</h3>${list(m.constraints)}<small>Volumes e SLOs são hipóteses de treino, não métricas reais do Nubank.</small></section></div>${timerHtml()}<div class="detail-grid"><div class="timeline">${m.timeline.map((t,i)=>`<section class="timeline-step" data-stage="${i}" data-minute="${t.minute}" data-duration="${t.duration}">${chip(`${String(t.minute).padStart(2,'0')}–${String(t.minute+t.duration).padStart(2,'0')} MIN`,'neutral')}<h3>${e(t.title)}</h3><p>${e(t.prompt)}</p><details><summary>Revelar critérios e aprofundamentos</summary><h4 style="margin-top:17px">Uma boa conversa inclui</h4>${list(t.expected)}<h4>Continue investigando</h4>${list(t.followUps)}</details></section>`).join('')}<details class="panel reading"><summary style="cursor:pointer;color:var(--purple)">Revelar mudança de cenário</summary><p style="margin:15px 0 0">${e(plain(m.twist))}</p></details></div><aside class="stack"><section class="panel"><h3>Seu raciocínio em rascunho</h3><p style="font-size:11px">Salvo automaticamente apenas neste navegador.</p><textarea data-note="${e(id)}" placeholder="Requisitos → invariantes → API → dados → fluxo → falhas → decisões…" aria-label="Anotações do simulado">${e(progress.notes[id]||'')}</textarea></section><section class="panel"><h3>Autoavaliação</h3><p style="font-size:11px">0: não cobriu · 1: superficial · 2: coerente · 3: justificou e testou limites.</p>${m.rubric.map((r,i)=>`<div class="rubric-row"><div><strong>${e(r.criterion)}</strong><small>Forte: ${e(r.excellent)}</small><small>A melhorar: ${e(r.weak)}</small></div><select data-score="${e(id)}:${i}" aria-label="Nota em ${e(r.criterion)}">${[0,1,2,3].map(n=>`<option ${Number(progress.scores[`${id}:${i}`]||0)===n?'selected':''}>${n}</option>`).join('')}</select></div>`).join('')}<div id="score-total" class="note"></div></section></aside></div>`}
function updateClock(){if(currentRoute!=='guided'&&(currentRoute!=='mocks'||!currentId))return;const t=Math.min(3600,elapsed()),remaining=Math.max(0,Math.ceil(3600-t));if($('#clock'))$('#clock').textContent=`${String(Math.floor(remaining/60)).padStart(2,'0')}:${String(remaining%60).padStart(2,'0')}`;if($('#timer-fill'))$('#timer-fill').style.width=`${t/36}%`;$$('[data-stage]').forEach(el=>el.classList.toggle('current',t>=Number(el.dataset.minute)*60&&t<(Number(el.dataset.minute)+Number(el.dataset.duration))*60));if(t>=3600&&timer.running){timer.elapsed=3600;timer.running=false;$('#timer-toggle').textContent='Sessão concluída';toast('60 minutos concluídos. Registre seus aprendizados.')}const m=D.mocks.find(x=>x.id===currentId);if(m&&$('#score-total')){const score=m.rubric.reduce((n,_,i)=>n+Number(progress.scores[`${m.id}:${i}`]||0),0);$('#score-total').textContent=`Sua avaliação: ${score} / ${m.rubric.length*3}. Escolha uma melhoria concreta para o próximo treino.`}}
function researchCases(id){const r=D.research;if(id){const c=r.cases.find(x=>x.id===id);if(!c)return notFound();return `<a class="back" href="#cases">← Casos e evidências</a>${title('Engenharia em contexto',c.title,c.summary)}<div class="reading"><section class="panel">${c.details.map((p,i)=>`<h3>${String(i+1).padStart(2,'0')} · ${i===0?'Entenda a restrição':'Aprofunde a decisão'}</h3><p>${e(p)}</p>`).join('')}</section>${id==='chargeback'?chargebackDeep():''}<section class="panel"><h2>Perguntas para defender o desenho</h2>${list(c.questions)}</section><section class="panel"><h3>De onde vem este caso</h3>${refs(c.sourceIds)}</section></div>`}return `${title('O domínio dá sentido ao desenho','Nubank na prática','Casos de engenharia publicados, relatos de candidatos e cenários autorais. Consulte a fonte para distinguir contexto histórico de capacidade atual.')}<div class="cards">${r.cases.map(c=>`<article class="card"><span class="card-icon">${icon('cases')}</span><h3><a href="#cases/${e(c.id)}">${e(c.title)}</a></h3><p>${e(c.summary)}</p><a href="#cases/${e(c.id)}" class="button small">Investigar o caso ↗</a></article>`).join('')}</div><div class="section-heading"><h2>O que candidatos relatam</h2><span class="chip amber">EVIDÊNCIA ANEDÓTICA</span></div><div class="two-col">${r.interview.reports.map(t=>`<article class="panel reading"><h3>${e(t.title)}</h3><p>${e(t.body)}</p><div class="note warning">${e(t.caveat)}</div>${refs(t.sourceIds)}</article>`).join('')}</div>`}
function chargebackDeep(){const sql=`-- Esboço PostgreSQL: associação durável, arquivo derivado.
CREATE TABLE batch_item (
  chargeback_id uuid PRIMARY KEY,
  batch_id uuid NOT NULL REFERENCES batch(id)
);
-- PRIMARY KEY impede pertencer a dois lotes neste modelo.
BEGIN;
-- Crie o lote antes, com janela e versão de contrato.
WITH eligible AS (
  SELECT c.id FROM chargeback c
  WHERE c.state = 'ELIGIBLE' AND c.created_at < :cutoff
    AND NOT EXISTS (SELECT 1 FROM batch_item bi
                    WHERE bi.chargeback_id = c.id)
  ORDER BY c.created_at, c.id
  FOR UPDATE OF c SKIP LOCKED
  LIMIT :chunk_size
)
INSERT INTO batch_item (chargeback_id, batch_id)
SELECT id, :batch_id FROM eligible;
COMMIT;
-- Não faça upload mantendo locks. Congele membros/versão,
-- gere em streaming, persista checksum, então envie.
-- O fechamento do lote precisa impedir novos membros:
-- lock/versão no batch e transição BUILDING -> FROZEN.`;return `<section class="panel"><h2>Uma solução inicial que dá para defender</h2><div class="mini-flow"><span>Elegível</span><i>→</i><span>Lote congelado</span><i>→</i><span>Arquivo</span><i>→</i><span>Envio incerto</span><i>→</i><span>Confirmado</span></div><p>Separe estado de negócio, atribuição ao lote, geração e entrega. Um worker pode cair em cada fronteira. Congele membros e payload exportado (ou uma revisão imutável), versão de layout, ordenação, encoding e bytes finais. Recriar um retry a partir de valores mutáveis pode mudar o checksum mesmo mantendo os mesmos pedidos.</p><h3>O invariante que realmente importa</h3><p><strong>Cada chargeback pertence a no máximo um lote lógico de envio.</strong> Uma chave única no banco prova isso sob concorrência. Uma variável em memória, cron ou lock com TTL sem fencing não prova. Se o domínio permitir correção, crie uma revisão explícita ligada ao original; não apague a história para reutilizar o identificador.</p><pre><code>${e(sql)}</code></pre><p>O exemplo não implementa todo o fechamento nem o protocolo do parceiro. SKIP LOCKED evita espera entre workers, mas não oferece uma visão consistente para relatórios. A seleção precisa de índices alinhados aos predicados; o custo inclui linhas examinadas e contenção, não apenas a quantidade retornada.</p><h3>Quatro janelas não significam quatro retries</h3><p>Esclareça se o limite recai sobre tentativas, uploads, nomes de arquivo ou lotes aceitos. Proteja a criação com uma chave única por parceiro/janela/slot e um contador ou autorização transacional de tentativas quando a cota for por tentativa; dois jobs não podem consumir a mesma vaga independentemente. Depois do timeout, represente UNKNOWN. O parceiro precisa oferecer receipt, consulta por batch_id, deduplicação, arquivo de retorno ou reconciliação. Sem isso, não existe uma solução local que garanta simultaneamente ausência de perda e de duplicação no efeito externo.</p><div class="table-wrap"><table><thead><tr><th>Peça</th><th>AWS</th><th>Azure</th><th>On-premises</th></tr></thead><tbody><tr><td>Fonte transacional</td><td>RDS PostgreSQL / Aurora PostgreSQL</td><td>Azure Database for PostgreSQL</td><td>PostgreSQL com HA, backup e WAL testados</td></tr><tr><td>Arquivo imutável</td><td>S3 + versionamento + política de retenção</td><td>Blob Storage + versionamento/imutabilidade</td><td>Object storage compatível S3; HA e retenção são sua operação</td></tr><tr><td>Execução</td><td>ECS/Fargate ou EC2; Lambda se duração e rede permitirem</td><td>Container Apps Jobs ou VM; Functions se limites permitirem</td><td>Workers em containers/VMs com supervisor</td></tr><tr><td>Sinal de trabalho</td><td>SQS + DLQ, se necessário</td><td>Service Bus queue + dead-letter</td><td>RabbitMQ quorum queue ou polling transacional</td></tr><tr><td>Conector no parceiro</td><td colspan="3">Agente autorizado próximo ao parceiro, canal seguro acordado, identidade própria, credenciais rotacionadas. Nuvem não remove restrições do contrato externo.</td></tr></tbody></table></div><h3>Uma evolução possível</h3><p>Comece com banco e workers. Adicione outbox se um commit precisar produzir eventos; separe geração de entrega quando recursos ou cadências diferirem; use backlog, idade do item mais antigo e reconciliação para justificar escala. Não migre para Kafka apenas para nomear um produto.</p></section>`}
function people(){const r=D.research;return `${title('Clareza vale mais que adivinhação','Entenda a conversa','Use o que está documentado para preparar decisões. A experiência pública dos entrevistadores dá contexto, mas não revela o que será perguntado.')}<div class="note"><strong>Formato confirmado no material fornecido:</strong> 60 minutos · Miro · apresentação pessoal de até cinco minutos · colaboração e justificativa das escolhas. Faça uma solução simples atravessar o fluxo inteiro antes de aprofundar.</div><section class="panel reading"><h2>O que merece sua atenção</h2><p>${e(r.interview.overview)}</p><div class="two-col">${r.interview.signals.map(s=>`<div class="bullet-row"><strong>${e(s.title)}</strong><p>${e(s.body)}</p>${refs(s.sourceIds)}</div>`).join('')}</div></section><div class="section-heading"><h2>Contexto profissional público</h2>${chip('ACESSO PARCIAL','amber')}</div><div class="people-grid">${r.people.map(p=>`<article class="panel reading"><div class="person-title"><div class="portrait">${p.name.split(' ').map(s=>s[0]).slice(0,2).join('')}</div><div><h2>${e(p.name)}</h2><p>${e(p.role)}</p></div></div><h3>O que foi possível verificar</h3>${p.verified.map(v=>`<div class="bullet-row"><p>${e(v.claim)}</p>${refs(v.sourceIds)}</div>`).join('')}<div class="note warning">${e(p.limits)}</div><h3>Como usar na preparação</h3>${p.preparation.map(x=>`<div class="bullet-row"><strong>${e(x.topic)}</strong><p>${e(x.reason)}</p><small>${e(x.caveat)}</small></div>`).join('')}</article>`).join('')}</div><section class="panel reading" style="margin-top:24px"><h2>Uma abertura que organiza a sessão</h2><p>“Antes de desenhar, vou confirmar o objetivo, quem usa o sistema e quais garantias não podem ser quebradas. Depois proponho um fluxo simples e aprofundamos as partes mais importantes. Posso começar pelo contrato com o sistema externo?”</p><h3>Quando uma pergunta te surpreender</h3><p>Repita a nova restrição, tire alguns segundos para pensar, mostre qual decisão muda e compare duas opções. Se não souber um detalhe de produto, explicite a propriedade que precisa verificar. Discordar com fundamento e rever a escolha fazem parte da colaboração.</p></section>`}
function plan(){const days=D.research.studyPlan;return `${title('Priorize antes de aprofundar','Um plano para chegar com clareza','A janela sugerida vai de 30 de outubro a 3 de novembro de 2026. Ajuste a carga ao seu tempo e concentre o esforço nas decisões que ainda não consegue explicar.')}<div class="note"><strong>Ordem de prioridade:</strong> requisitos e invariantes → modelo de dados e concorrência → idempotência e falhas externas → fluxo simples → escala e operação → alternativas de infraestrutura. O atlas é consulta; os simulados mostram as lacunas.</div><div class="plan-grid">${days.map((d,i)=>`<section class="panel plan-day"><span class="eyebrow">${e(d.day)}</span><h2>${e(d.title)}</h2><ul class="checklist">${d.tasks.map((t,j)=>{const key=`day-${i}-${j}`;return `<li class="${progress.checks.includes(key)?'done':''}"><input type="checkbox" data-check="${key}" id="${key}" ${progress.checks.includes(key)?'checked':''}><label for="${key}">${e(t)}</label></li>`}).join('')}</ul></section>`).join('')}</div><section class="panel reading" style="margin-top:24px"><h2>Seu roteiro de 60 minutos</h2><div class="table-wrap"><table><thead><tr><th>Janela sugerida</th><th>Entrega na conversa</th><th>Pergunta de controle</th></tr></thead><tbody>${[['0–5','Apresentação breve e alinhamento','Qual objetivo precisamos atender?'],['5–12','Requisitos, restrições e invariantes','O que seria uma falha inaceitável?'],['12–22','API, entidades e fluxo simples','De onde vem a verdade?'],['22–38','Concorrência, timeout e recuperação','Se cair aqui, como retoma?'],['38–50','Escala e alternativas','Qual medida justificaria mudar a solução?'],['50–57','Segurança, observabilidade e operação','Como detectamos uma falha silenciosa?'],['57–60','Recapitular e discutir limites','O que decidimos e o que ainda verificaríamos?']].map(row=>`<tr>${row.map(c=>`<td>${e(c)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p style="margin:18px 0 0">A divisão é uma estratégia de treino, não uma agenda oficial. Siga o ritmo da conversa e a orientação das pessoas entrevistadoras.</p></section>`}
function techCards(){return `<div class="tech-grid">${D.technologies.map(t=>`<article class="tech-card">${t.logo?`<img class="tech-logo" src="${e(t.logo)}" alt="${e(t.name)}" loading="lazy">`:`<span class="tech-fallback" aria-hidden="true">${e(t.name.slice(0,2))}</span>`}<div><strong><a href="${e(t.url)}" target="_blank" rel="noopener">${e(t.name)} ↗</a></strong><p>${e(t.role)}</p>${t.logoSource?`<a href="${e(t.logoSource)}" target="_blank" rel="noopener"><small>${e(t.logoKind||'Origem oficial do ícone')}</small></a>`:'<small>Marca não incluída; consulte a documentação.</small>'}</div></article>`).join('')}</div>`}
function sources(){let items=D.sources.filter(s=>(!filter.q||matches(s,filter.q))&&(!filter.category||s.type===filter.category));return `${title('Rastreabilidade faz parte do estudo','Biblioteca & fontes','Documentação primária, engenharia do Nubank, relatos públicos e materiais fornecidos. Uma fonte histórica descreve seu contexto de publicação.')}<div class="tabs"><button class="tab ${tab!=='technologies'?'active':''}" data-tab="overview">Fontes de pesquisa</button><button class="tab ${tab==='technologies'?'active':''}" data-tab="technologies">Tecnologias & marcas</button></div>${tab==='technologies'?`<div class="note">Logos e ícones são obtidos de páginas e repositórios oficiais quando disponíveis; cada ativo tem origem vinculada. Usados para identificação educacional, sem afiliação ou endosso. Uma marca não implica adoção pelo Nubank. A lista é representativa, não universal.</div>${techCards()}`:`<div class="filters"><input type="search" id="filter-q" aria-label="Buscar fonte" placeholder="Título, assunto, domínio…" value="${e(filter.q)}"><select id="filter-category" aria-label="Tipo de evidência">${options(D.sources.map(s=>s.type),filter.category,'Todos os tipos de evidência')}</select></div><div class="result-line"><span>${items.length} referências</span><span>Pesquisa consolidada em 30/10/2026</span></div><section class="panel">${paginate(items,s=>`<article class="source-card">${chip(s.type||'Referência','neutral')} ${s.date?`<small style="color:var(--muted)">${e(s.date)}</small>`:''}<h3>${s.url?`<a href="${e(s.url)}" target="_blank" rel="noopener">${e(s.title)} ↗</a>`:e(s.title)}</h3><p>${e(s.summary)}</p>${s.url?`<span class="url">${e(s.url)}</span>`:'<small>Material fornecido pelo candidato; arquivo original não publicado.</small>'}</article>`,30)}</section><div class="note"><strong>Limites da pesquisa:</strong> não houve acesso a conteúdo privado do LinkedIn ou a uma rubrica interna. Não foi possível inspecionar todo post, comentário ou vídeo da internet. Relatos têm viés de seleção; o plano e as perguntas são material autoral de preparação. As referências fundamentam mecanismos, não uma promessa de aprovação.</div>`}`}
function lab(id){const which=id||'queue';return `${title('Faça a falha aparecer','Laboratório de decisões','Mude uma hipótese, observe o efeito e explique a decisão. Modelos didáticos determinísticos; não são benchmarks de serviços.')}<div class="tabs">${[['queue','Fila & capacidade'],['idempotency','Retry & idempotência'],['latency','Latência & fan-out'],['sharding','Particionamento']].map(([k,t])=>`<a href="#lab/${k}" class="tab ${which===k?'active':''}">${t}</a>`).join('')}</div>${which==='queue'?queueLab():which==='idempotency'?idempotencyLab():which==='latency'?latencyLab():shardingLab()}`}
function control(id,label,min,max,value,unit,step=1){return `<label class="control"><span>${label}<strong id="${id}-value">${value} ${unit}</strong></span><input id="${id}" type="range" min="${min}" max="${max}" value="${value}" step="${step}" data-unit="${unit}"></label>`}
function queueLab(){return `<div class="detail-grid"><section class="panel reading"><h2>Uma fila compra tempo. Não cria capacidade.</h2><p>Um pico dura 60 segundos. O modelo abaixo assume chegadas uniformes, serviço constante e backlog inicial zero. Na prática, variância, retries e hot partitions pioram a cauda.</p>${control('arrival','Chegadas por segundo',100,10000,3000,'req/s',100)}${control('workers','Workers paralelos',1,32,8,'workers')}${control('service','Tempo por operação',1,50,5,'ms')}<div class="note" id="queue-verdict"></div></section><section class="panel"><h3>Backlog durante o pico</h3><div class="bar-chart" id="queue-bars"></div><div class="lab-labels"><span>0s</span><span>30s</span><span>60s</span></div><p style="font-size:11px;margin-top:22px">Fila crescendo significa trabalho acumulado. Dimensione pelo tempo até o prazo e pela idade da mensagem mais antiga.</p></section></div><div class="lab-stats" style="margin-top:22px"><div class="lab-stat"><strong id="capacity"></strong><span>capacidade teórica / segundo</span></div><div class="lab-stat"><strong id="backlog"></strong><span>pendências após 60 segundos</span></div><div class="lab-stat"><strong id="drain"></strong><span>para drenar sem novas chegadas</span></div></div><section class="panel reading" style="margin-top:22px"><h3>O que dizer na entrevista</h3><p>“A fila desacopla o pico, mas se λ > μ por tempo suficiente, o backlog cresce sem limite. Em λ = μ não há folga; a variabilidade real pode acumular espera. Eu limitaria admissão, investigaria o gargalo por partição e escalaria consumidores apenas até a capacidade do recurso seguinte.”</p><pre><code>capacidade μ = workers × 1000 / tempo_ms
backlog(60s) = max(0, (λ − μ) × 60)
tempo_de_drenagem = backlog / μ  # sem novas chegadas
Little: L = λ × W              # sistema estável e mesma fronteira</code></pre><p>CPU-bound exige capacidade de CPU; I/O-bound pode ganhar com concorrência limitada. Mais workers disputando o mesmo lock podem reduzir throughput.</p>${refs(['little-law'])}</section>`}
function updateQueue(){if(!$('#arrival'))return;const a=+$('#arrival').value,w=+$('#workers').value,s=+$('#service').value,c=w*1000/s,b=Math.max(0,(a-c)*60),dr=b/c;$('#capacity').textContent=fmt(Math.round(c));$('#backlog').textContent=fmt(Math.round(b));$('#drain').textContent=`${dr.toFixed(1)}s`;$('#queue-verdict').textContent=a>=c?`Saturado: utilização teórica ${(a/c*100).toFixed(0)}%. Reduza entrada, tempo de serviço ou gargalo antes de confiar na fila.`:`Utilização teórica ${(a/c*100).toFixed(0)}%. Existe folga média, mas picos e caudas exigem medir.`;$('#queue-bars').innerHTML=Array.from({length:12},(_,i)=>`<div class="bar" style="height:${b?((i+1)/12)*88:2}%"><span>${i===11?fmt(Math.round(b)):''}</span></div>`).join('')}
let payments={balance:10000,attempts:0,effects:0,seen:false};
function idempotencyLab(){payments={balance:10000,attempts:0,effects:0,seen:false};return `<div class="detail-grid"><section class="panel reading"><h2>O commit aconteceu. A resposta sumiu.</h2><p>Um cliente tenta pagar R$ 100. O servidor debita, mas a rede perde o ACK. Reenvie a mesma operação com e sem chave idempotente.</p><label class="control"><span>Proteção transacional <strong>mesma chave, mesmo payload</strong></span><select id="idem-mode" style="width:100%"><option value="on">Chave única + efeito na mesma transação</option><option value="off">Sem deduplicação</option></select></label><div class="actions"><button class="button primary" id="pay">Enviar / repetir pagamento</button><button class="button" id="pay-reset">Reiniciar</button></div><div class="note">O primeiro ACK é perdido intencionalmente. A retenção da chave, o hash do payload e a fronteira transacional são parte do contrato.</div></section><section class="panel"><h3>Eventos observados</h3><div class="log" id="payment-log">Pronto. Conta com R$ 10.000,00.<br>Operação lógica: payment-42.</div></section></div><div class="lab-stats" style="margin-top:22px"><div class="lab-stat"><strong id="pay-balance">R$ 10.000</strong><span>saldo registrado</span></div><div class="lab-stat"><strong id="pay-attempts">0</strong><span>tentativas recebidas</span></div><div class="lab-stat"><strong id="pay-effects">0</strong><span>efeitos financeiros</span></div></div><section class="panel reading" style="margin-top:22px"><h3>Por que um GET seguido de SET não basta?</h3><p>Duas requisições podem ler “chave ausente” antes de gravar. Use exclusão por índice único e execute efeito e registro da resposta na mesma transação. Um SET NX com TTL separado do débito deixa janelas de falha. Uma chamada externa exige participação do receptor ou reconciliação.</p><pre><code>BEGIN;
INSERT INTO request_key (tenant, key, payload_hash)
VALUES (:tenant, :key, :hash)
ON CONFLICT (tenant,key) DO NOTHING RETURNING key;
-- Em READ COMMITTED, o INSERT aguarda a concorrente resolver.
-- Se NÃO inseriu: fazer SELECT em nova instrução/snapshot,
-- conferir hash; divergência = erro. Resultado existente =
-- COMMIT/retorno sem executar o débito abaixo. Linha ausente
-- exige retry controlado. Retenção não pode apagar chave ativa.
-- Só o ramo que inseriu a chave continua:
UPDATE account SET available = available - :amount
WHERE id = :id AND available >= :amount;
-- exigir exatamente uma linha atualizada ou abortar
INSERT INTO ledger_entry (...) VALUES (...); -- lançamento balanceado
UPDATE request_key SET response = :result WHERE ...;
COMMIT;
-- só então enviar ACK; persistir resultado permite retry seguro</code></pre><p>O esboço exige validação de autorização e moeda, valores em unidade mínima/decimal e lançamentos de dupla entrada. Exatamente uma aplicação local não significa exactly-once em qualquer integração.</p>${refs(['pg-insert','pg-transactions','aws-idempotent'])}</section>`}
function latencyLab(){return `<div class="detail-grid"><section class="panel reading"><h2>Uma cauda rara pode virar rotina.</h2><p>Suponha chamadas independentes e uma probabilidade fixa de cada dependência ultrapassar 200 ms. A resposta espera todas elas.</p>${control('fanout','Dependências em paralelo',1,100,20,'chamadas')}${control('tail','Chance de cada chamada exceder 200 ms',1,20,1,'%')}<div class="note" id="latency-verdict"></div></section><section class="panel reading"><h3>Probabilidade de alguma chamada lenta</h3><strong id="tail-result" style="font:700 68px Manrope;color:var(--purple)"></strong><pre><code>P(alguma lenta) = 1 − (1 − p)^n</code></pre><p>Independência é simplificação. Falhas correlacionadas alteram o resultado. A fórmula não calcula o p99 final; estima a chance de exceder um limiar.</p></section></div><section class="panel reading" style="margin-top:22px"><h3>Opções que mudam o caminho crítico</h3><p>Agregação materializada evita fan-out no request ao preço de freshness; cache exige invalidação e proteção contra stampede; paralelismo reduz soma de esperas, mas mantém o máximo. Timeout com orçamento por dependência, degradação de campos opcionais e isolamento de pools ajudam a limitar a falha.</p><p>Hedged requests só fazem sentido com idempotência, cancelamento efetivo e capacidade sobrando. Retry indiscriminado em saturação aumenta a fila.</p>${refs(['tail-at-scale'])}</section>`}
function hash(s){let h=2166136261;for(const c of s)h=Math.imul(h^c.charCodeAt(0),16777619);return h>>>0}
function shardingLab(){return `<div class="detail-grid"><section class="panel reading"><h2>O tamanho total não explica a partição quente.</h2><p>Distribuímos 10 mil requisições entre mil contas fictícias. Uma conta pode concentrar tráfego. Virtual nodes equilibram chaves; não dividem automaticamente uma única chave quente.</p>${control('shards','Partições',2,16,8,'shards')}${control('hot','Tráfego da maior conta',0,90,30,'%')}<div class="note" id="shard-verdict"></div></section><section class="panel"><h3>Requisições por partição</h3><div class="bar-chart" id="shard-bars"></div><div class="lab-labels"><span>Partição 0</span><span id="last-shard"></span></div></section></div><section class="panel reading" style="margin-top:22px"><h3>Mudar o hash não muda o invariante</h3><p>Dividir uma conta financeira em subchaves pode quebrar a serialização das atualizações do saldo. Antes de aplicar salting, identifique operações comutativas, fronteiras de autorização e o custo de agregar ou coordenar. Replicação de leitura não distribui necessariamente a escrita no líder.</p><p>O experimento usa hash módulo N. Rendezvous ou consistent hashing reduz remapeamento ao alterar o conjunto de nós, mas ainda precisa de migração, roteamento por versão e fencing para escritores antigos.</p>${refs(['dynamo-paper','dynamodb-partition-keys'])}</section>`}
function updateLabs(){updateQueue();if($('#fanout')){const n=+$('#fanout').value,p=+$('#tail').value/100,v=(1-(1-p)**n)*100;$('#tail-result').textContent=`${v.toFixed(1)}%`;$('#latency-verdict').textContent=`Com ${n} dependências, a chance de ao menos uma ultrapassar o limiar é ${v.toFixed(1)}%. Considere reduzir dependências do caminho crítico.`}if($('#shards')){const n=+$('#shards').value,hot=+$('#hot').value,counts=Array(n).fill(0);for(let i=0;i<10000;i++){const key=i<hot*100?'hot-account':`account-${i%1000}`;counts[hash(key)%n]++}const max=Math.max(...counts);$('#shard-bars').innerHTML=counts.map((v,i)=>`<div class="bar" style="height:${v/max*88}%" title="Partição ${i}: ${v} requisições"><span>${v}</span></div>`).join('');$('#last-shard').textContent=`Partição ${n-1}`;$('#shard-verdict').textContent=`A maior partição recebe ${(max/100).toFixed(1)}% do tráfego: ${(max/(10000/n)).toFixed(1)}× a média. Meça distribuição por chave, não só a média global.`}}
function notFound(){return `<div class="empty"><h1>Conteúdo não encontrado</h1><a class="button" href="#home">Voltar ao início</a></div>`}
function render(keepScroll=false){mindMap.destroy();playbook.destroy();const pos=scrollY,active=document.activeElement;const focusAttr=['data-tab','data-cap','data-ledger-action','data-ledger-file','data-cloud','data-read'].find(k=>active?.hasAttribute(k));const focusSelector=active?.id?`#${CSS.escape(active.id)}`:focusAttr?`[${focusAttr}="${CSS.escape(active.getAttribute(focusAttr))}"]`:null;navRender();let html='';try{html= currentRoute==='home'?home():currentRoute==='map'?mindMap.html(D.mindmap,currentId):currentRoute==='playbook'?playbook.html(D.playbook,currentId):currentRoute==='atlas'?currentId?archDetail(currentId):atlas():currentRoute==='compare'?comparePage(currentId):currentRoute==='questions'?questions():currentRoute==='flashcards'?flashcards():currentRoute==='guided'?guidedPage(currentId):currentRoute==='mocks'?currentId?mockDetail(currentId):mocks():currentRoute==='lab'?lab(currentId):currentRoute==='course'?coursePage(currentId):currentRoute==='videos'?videosPage(currentId):currentRoute==='foundations'?foundationPage(currentId):currentRoute==='ledger'?ledgerPage(currentId):currentRoute==='cases'?researchCases(currentId):currentRoute==='people'?people():currentRoute==='plan'?plan():currentRoute==='sources'?sources():notFound();$('#main').innerHTML=html;bind();bindLedger();bindFoundations();bindVideos();bindCourse();bindGuided();if(currentRoute==='map')mindMap.bind(D.mindmap,currentId);if(currentRoute==='playbook')playbook.bind();enhanceReading();updateClock();updateLabs();if(keepScroll){scrollTo(0,pos);if(focusSelector)$(focusSelector)?.focus({preventScroll:true})}}catch(err){console.error(err);$('#main').innerHTML='<div class="empty">Não foi possível montar esta página. <a href="#home">Voltar ao início</a></div>'}}
function route(){rememberPlace();const [base,query]=(location.hash.slice(1)||'home').split('?');const parts=base.split('/');const next=parts[0];if(next!==currentRoute||parts[1]!==currentId){filter={q:'',category:'',level:'',priority:'',saved:false,page:1};tab='overview'}currentRoute=next;currentId=decodeURIComponent(parts[1]||'');if(currentRoute==='compare'&&currentId)compare[0]=currentId;const params=new URLSearchParams(query);if(params.has('q'))filter.q=params.get('q');if(currentRoute==='guided'){guidedStep=Math.max(0,Math.min(9,(parseInt(params.get('step'),10)||1)-1));guidedRehearse=params.get('mode')==='rehearse';guidedRevealed=false;guidedFinal=false;}if(currentRoute==='atlas'&&['overview','decisions','internals','code','operations','deployments'].includes(params.get('tab')))tab=params.get('tab');$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false');render();scrollTo(0,0);activeHash=location.hash||'#home';if(requestedResumeY!==null){const y=requestedResumeY;requestedResumeY=null;requestAnimationFrame(()=>scrollTo(0,y));}}
function toggle(array,id){const index=array.indexOf(id);index>=0?array.splice(index,1):array.push(id);return save()}
function bind(){$$('[data-cloud]').forEach(b=>b.onclick=()=>{cloud=b.dataset.cloud;render(true)});for(const kind of ['q','category','level','priority']){const el=$(`#filter-${kind}`);if(el)el.addEventListener(kind==='q'?'input':'change',()=>{const start=el.selectionStart;filter[kind]=el.value;filter.page=1;if(currentRoute==='videos'){updateVideoCatalogue();return}render(true);const next=$(`#filter-${kind}`);next?.focus();if(kind==='q')next.setSelectionRange(start,start)})}$$('[data-page]').forEach(b=>b.onclick=()=>{filter.page=+b.dataset.page;render();scrollTo(0,200)});$$('[data-tab]').forEach(b=>b.onclick=()=>{tab=b.dataset.tab;if(currentRoute==='atlas')history.replaceState(null,'',`#atlas/${encodeURIComponent(currentId)}?tab=${tab}`);activeHash=location.hash;render(true)});$$('[data-read]').forEach(b=>b.onclick=()=>{toggle(progress.read,b.dataset.read);render(true)});$$('[data-compare]').forEach(b=>b.onchange=()=>{compare[+b.dataset.compare]=b.value;render(true)});$$('[data-known]').forEach(b=>b.onclick=()=>{const persisted=toggle(progress.known,b.dataset.known);b.textContent=progress.known.includes(b.dataset.known)?'✓ Dominada':'Já consigo explicar';b.closest('.question').classList.toggle('mastered',progress.known.includes(b.dataset.known));if(persisted)toast('Progresso salvo no dispositivo')});$$('[data-bookmark]').forEach(b=>b.onclick=()=>{const persisted=toggle(progress.bookmarks,b.dataset.bookmark);b.textContent=progress.bookmarks.includes(b.dataset.bookmark)?'★ Salva':'☆ Revisar depois';if(persisted)toast('Lista de revisão atualizada')});if($('#only-saved'))$('#only-saved').onclick=()=>{filter.saved=!filter.saved;filter.page=1;render()};if($('#reveal-flash'))$('#reveal-flash').onclick=()=>{$('#flash-answer').classList.remove('hidden');$('#reveal-flash').disabled=true};if($('#next-flash'))$('#next-flash').onclick=()=>{activeFlash+=1+Math.floor(Math.random()*37);render(true)};$$('[data-flash-known]').forEach(b=>b.onclick=()=>{if(!progress.known.includes(b.dataset.flashKnown))progress.known.push(b.dataset.flashKnown);save();render(true)});$$('[data-node]').forEach(n=>{const select=()=>{const a=diagramModel||D.architectures.find(x=>x.id===currentId),node=a?.nodes.find(x=>x.id===n.dataset.node);$$('[data-node]').forEach(x=>x.classList.remove('selected'));n.classList.add('selected');$('#node-detail').innerHTML=`<strong>${e(node?.label)}</strong><br>${e(node?.detail||'Responsabilidade conforme o fluxo apresentado.')} ${node?.tech?`<br><small>Tecnologia representativa: ${e(node.tech)}</small>`:''}`};n.onclick=select;n.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();select()}}});if($('#animate-toggle'))$('#animate-toggle').onclick=()=>{const d=$('#diagram');d.classList.toggle('paused');$('#animate-toggle').textContent=d.classList.contains('paused')?'Animar fluxo':'Pausar fluxo'};if($('#timer-toggle'))$('#timer-toggle').onclick=()=>{if(timer.running){timer.elapsed=elapsed();timer.running=false}else if(timer.elapsed<3600){timer.start=Date.now();timer.running=true}$('#timer-toggle').textContent=timer.running?'Pausar':'Continuar';updateClock()};if($('#timer-reset'))$('#timer-reset').onclick=()=>{timer.elapsed=0;timer.running=false;$('#timer-toggle').textContent='Iniciar sessão';updateClock()};$$('[data-note]').forEach(t=>t.oninput=()=>{progress.notes[t.dataset.note]=t.value;save()});$$('[data-score]').forEach(t=>t.onchange=()=>{progress.scores[t.dataset.score]=+t.value;save();updateClock()});$$('[data-check]').forEach(t=>t.onchange=()=>{toggle(progress.checks,t.dataset.check);t.closest('li').classList.toggle('done',t.checked)});$$('input[type=range]').forEach(x=>x.oninput=()=>{$(`#${x.id}-value`).textContent=`${x.value} ${x.dataset.unit}`;updateLabs()});if($('#pay'))$('#pay').onclick=()=>{payments.attempts++;const protectedMode=$('#idem-mode').value==='on';let msg;if(protectedMode&&payments.seen){msg='<span class="ok">Chave encontrada → resultado anterior; nenhum novo débito.</span>'}else{payments.balance-=100;payments.effects++;payments.seen=true;msg=payments.attempts===1?'<span class="bad">COMMIT concluído. ACK perdido → timeout no cliente.</span>':`<span class="${payments.effects>1?'bad':'ok'}">COMMIT: novo débito aplicado ${payments.effects>1?'(duplicação!)':''}.</span>`}$('#payment-log').innerHTML+=`<br>#${payments.attempts} ${msg}`;$('#pay-balance').textContent=new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL',maximumFractionDigits:0}).format(payments.balance);$('#pay-attempts').textContent=payments.attempts;$('#pay-effects').textContent=payments.effects};if($('#pay-reset'))$('#pay-reset').onclick=()=>{payments={balance:10000,attempts:0,effects:0,seen:false};render(true)};if($('#idem-mode'))$('#idem-mode').onchange=()=>{payments={balance:10000,attempts:0,effects:0,seen:false};$('#payment-log').innerHTML='Novo experimento. Conta com R$ 10.000,00.';$('#pay-balance').textContent='R$ 10.000';$('#pay-attempts').textContent='0';$('#pay-effects').textContent='0'};}
function search(){const q=$('#global-search').value;if(q.length<2){$('#search-results').innerHTML='<p style="margin:20px 0;font-size:12px">Digite ao menos dois caracteres. Pesquise mecanismos, problemas ou tecnologias.</p>';return}const items=[...D.playbook.cases.filter(x=>matches({title:x.title,brief:x.brief,invariants:x.invariants},q)).slice(0,4).map(x=>({title:x.title,sub:'Roteiro do dia · fala e desenho em 10 etapas',url:`#playbook/${x.id}`})),...D.mindmap.nodes.filter(x=>matches({title:x.label,summary:x.summary,keywords:x.keywords},q)).slice(0,4).map(x=>({title:x.label,sub:'Mapa mental · '+D.mindmap.groups.find(g=>g.id===x.group).label,url:`#map/${x.id}`})),...D.guided.cases.filter(x=>matches({title:x.title,subtitle:x.subtitle,brief:x.brief},q)).slice(0,3).map(x=>({title:x.title,sub:'Entrevista guiada · 60 min',url:`#guided/${x.id}`})),...D.course.lessons.filter(x=>matches({title:x.title,topics:x.topics},q)).slice(0,3).map(x=>({title:x.title,sub:'Curso LINUXtips · aula '+x.number,url:`#course/${x.id}`})),...D.videos.videos.filter(x=>matches({title:x.title,topic:x.topic,channel:x.channel},q)).slice(0,3).map(x=>({title:x.title,sub:'Videoteca · '+x.channel,url:`#videos/${x.id}`})),...D.foundations.chapters.filter(x=>matches(x,q)).slice(0,3).map(x=>({title:x.title,sub:'Fundamentos distribuídos',url:`#foundations/${x.id}`})),...D.ledger.sections.filter(x=>matches(x,q)).slice(0,3).map((x)=>({title:x.title,sub:'Ledger bancário · capítulo técnico',url:`#ledger/${x.id}`})),...D.architectures.filter(x=>matches(x,q)).sort((a,b)=>Number(matches(b.title,q))-Number(matches(a.title,q))).slice(0,5).map(x=>({title:x.title,sub:`Atlas · ${x.category}`,url:`#atlas/${x.id}`})),...D.questions.filter(x=>matches({question:x.question,category:x.category},q)).slice(0,5).map(x=>({title:x.question,sub:`Pergunta · ${x.category}`,url:`#questions/${x.id}`})),...D.mocks.filter(x=>matches({title:x.title,domain:x.domain},q)).slice(0,3).map(x=>({title:x.title,sub:'Simulado de 60 min',url:`#mocks/${x.id}`})),...D.research.cases.filter(x=>matches(x,q)).slice(0,3).map(x=>({title:x.title,sub:'Caso de engenharia',url:`#cases/${x.id}`}))];$('#search-results').innerHTML=items.length?items.map(x=>`<a href="${x.url}">${e(x.title)}<small>${e(x.sub)}</small></a>`).join(''):'<p style="padding:20px">Nenhum resultado.</p>';$$('#search-results a').forEach(a=>a.onclick=()=>$('#search-dialog').close())}
function openSearch(){if(document.body.classList.contains('map-is-full'))$('#map-full')?.click();$('#search-dialog').showModal();$('#global-search').focus();search()}
$('#search-launch').onclick=openSearch;$('#global-search').oninput=search;document.addEventListener('keydown',ev=>{if((ev.metaKey||ev.ctrlKey)&&ev.key==='k'){ev.preventDefault();openSearch()}if(ev.key==='Escape')$('#sidebar').classList.remove('open')});$('#menu').onclick=()=>{$('#sidebar').classList.toggle('open');$('#menu').setAttribute('aria-expanded',$('#sidebar').classList.contains('open'))};$('.skip').onclick=ev=>{ev.preventDefault();$('#main').focus()};document.addEventListener('click',ev=>{if($('#sidebar').classList.contains('open')&&!$('#sidebar').contains(ev.target)&&!$('#menu').contains(ev.target)){$('#sidebar').classList.remove('open');$('#menu').setAttribute('aria-expanded','false')}});$('#theme').onclick=()=>{document.body.classList.toggle('dark');(()=>{try{localStorage.setItem('nuarch-theme',document.body.classList.contains('dark')?'dark':'light')}catch{}})()};try{document.body.classList.toggle('dark',localStorage.getItem('nuarch-theme')==='dark')}catch{}
$('#export-progress').onclick=()=>{const blob=new Blob([JSON.stringify({version:1,exportedAt:new Date().toISOString(),progress},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='nuarch-meu-progresso.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('Progresso exportado')};$('#import-progress').onclick=()=>$('#progress-file').click();$('#progress-file').onchange=async ev=>{try{const data=JSON.parse(await ev.target.files[0].text());if(data.version!==1||!data.progress||!['known','bookmarks','read','checks'].every(k=>Array.isArray(data.progress[k])&&data.progress[k].every(x=>typeof x==='string'))||!data.progress.notes||Array.isArray(data.progress.notes)||typeof data.progress.notes!=='object'||!Object.values(data.progress.notes).every(x=>typeof x==='string')||!data.progress.scores||Array.isArray(data.progress.scores)||typeof data.progress.scores!=='object'||!Object.values(data.progress.scores).every(x=>Number.isInteger(x)&&x>=0&&x<=3))throw new Error();progress={...progress,...data.progress};const persisted=progressStore.replace(progress);if(persisted)progress=progressStore.snapshot();render(true);if(persisted)toast('Progresso importado')}catch{toast('Arquivo de progresso inválido. Use uma exportação do nuArch.')}ev.target.value=''};
