async function init(){try{const responses=await Promise.all(['architectures','practice','research','logos','ledger','foundations','videos','course-linux','guided','mindmap','playbook'].map(name=>fetch(`data/${name}.json${name==='playbook'?'?v=20261101-context1':''}`).then(r=>{if(!r.ok)throw new Error(`Falha ao carregar ${name}`);return r.json()})));const [a,p,r,l,g,f,v,c,w,m,b]=responses;D={playbook:b,mindmap:m,guided:w,course:c,videos:v,foundations:f,ledger:g,architectures:a.architectures,technologies:a.technologies,questions:p.questions,mocks:p.mocks,research:r,practiceMeta:p.meta,sources:[]};const all=[...r.sources,...a.sources,...p.sources,...g.sources,...f.sources,...v.sources,...c.sources,...w.sources,...m.sources,...b.sources];const byUrl=new Map();for(const s of all){sourceMap[s.id]=s;if(!byUrl.has(s.url||s.id))byUrl.set(s.url||s.id,s)}D.sources=[...byUrl.values()];D.technologies=D.technologies.map(t=>{const logo=l.entries.find(x=>normalize(x.name)===normalize(t.name)||x.id===t.id||(t.id==='elastic'&&x.id==='elasticsearch'));return logo?{...t,assetId:logo.id,logo:logo.logo,logoSource:logo.sourceUrl,logoKind:logo.kind}:t});for(const logo of l.entries){if(!D.technologies.some(t=>t.id===logo.id||t.assetId===logo.id||normalize(t.name)===normalize(logo.name)))D.technologies.push({id:logo.id,name:logo.name,url:logo.officialWebsite,role:'Opção de implementação',logo:logo.logo,logoSource:logo.sourceUrl,logoKind:logo.kind})}route()}catch(err){console.error(err);$('#main').innerHTML=`<section class="panel"><h1>O acervo ainda não carregou.</h1><p>Verifique sua conexão e recarregue a página. O portal precisa ser aberto por HTTP, não diretamente como arquivo.</p><button class="button" onclick="location.reload()">Tentar novamente</button></section>`}}

function cloudTechnology(service){const n=normalize(service);const aliases=cloud==='aws'?{'step-functions':['step functions'],'api-gateway':['api gateway'],'msk':['msk'],'aurora':['aurora'],'rds':['rds'],'dynamodb':['dynamodb'],'sqs':['sqs'],'sns':['sns'],'eventbridge':['eventbridge'],'kinesis':['kinesis'],'lambda':['lambda'],'ecs':['ecs','fargate'],'eks':['eks'],'s3':['s3'],'elasticache':['elasticache'],'cloudwatch':['cloudwatch'],'ec2':['ec2']}:cloud==='azure'?{'azure-postgresql':['azure database for postgresql'],'azure-service-bus':['service bus'],'azure-event-hubs':['event hubs'],'azure-container-apps':['container apps'],'azure-functions':['functions'],'azure-aks':['aks'],'azure-cosmos-db':['cosmos'],'azure-blob':['blob'],'azure-api-management':['api management'],'azure-redis':['managed redis','cache for redis'],'azure-monitor':['azure monitor'],'azure-key-vault':['key vault'],'azure-front-door':['front door'],'azure-app-gateway':['application gateway'],'azure-vm':['virtual machine','azure vm']}:{};for(const [id,terms] of Object.entries(aliases)){if(terms.some(t=>n.includes(t))){const t=D.technologies.find(x=>x.id===id||x.assetId===id);if(t?.logo)return t}}return D.technologies.find(x=>x.logo&&n.includes(normalize(x.name).replace(/^apache /,'')))}
function cloudLogo(service){const t=cloudTechnology(service);return t?.logo?`<img src="${e(t.logo)}" class="tech-logo" alt="${e(t.name)}" loading="lazy">`:''}
function deploymentView(a){const d=a.deployments;if(!d)return '<div class="note">Implementação depende das garantias requeridas. Consulte os serviços oficiais na biblioteca.</div>';const selected=d[cloud]||d.aws;const titles={aws:'Amazon Web Services',azure:'Microsoft Azure',onprem:'On-premises / autogerenciado'};const comps=arr(selected.components);const mapped={...a,title:`${a.title} · ${titles[cloud]}`,nodes:a.nodes.map((n,i)=>{const c=comps.find(c=>c.role===n.label)||comps[i];return {...n,label:c?c.service.split(' / ')[0].split(' + ')[0]:n.label,detail:c?`${c.role}: ${c.service}. ${c.reason}`:n.detail,tech:null,logoOverride:c?cloudTechnology(c.service)?.logo:null}})};return `<section class="panel"><h2>O padrão continua. A operação muda.</h2><p>Estas são implementações possíveis para o exercício. Nenhuma coluna afirma a infraestrutura real do Nubank, equivalência perfeita entre produtos ou adequação sem validação.</p><div class="tabs">${Object.entries(titles).map(([id,name])=>`<button class="tab ${cloud===id?'active':''}" data-cloud="${id}">${name}</button>`).join('')}</div>${diagram(mapped)}<div class="cards">${comps.map(c=>`<article class="card"><div style="display:flex;gap:12px;align-items:center">${cloudLogo(c.service)}<div><span class="eyebrow" style="font-size:8px;margin:0">${e(c.role)}</span><h3 style="margin:7px 0">${e(c.service)}</h3></div></div><p style="margin:14px 0 0">${e(c.reason)}</p>${refs([c.sourceId])}</article>`).join('')}</div><div class="note">${list(selected.notes)}</div></section><section class="panel"><h2>Compare as três implementações</h2><div class="table-wrap"><table><thead><tr><th>Papel</th><th>AWS</th><th>Azure</th><th>On-premises</th></tr></thead><tbody>${a.nodes.map((n,i)=>`<tr><td>${e(n.label)}</td>${['aws','azure','onprem'].map(k=>{const c=arr(d[k]?.components).find(c=>c.role===n.label)||arr(d[k]?.components)[i];return `<td><strong>${e(c?.service||'Conforme contrato')}</strong><br>${e(c?.reason||'')}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="note warning"><strong>Não troque apenas o logo:</strong> valide ordering, retenção, replay, ack, partições, transações, quotas, failover, custo de transferência e responsabilidade por patch/backup/restore. SQS/Service Bus não são substitutos transparentes de Kafka; Event Hubs com endpoint Kafka exige verificar as APIs e garantias usadas.</div></section>`}

// Ledger chapter: the browser experiment illustrates boundaries, not a bank runtime.
const ledgerSections=['Mapa & fluxo','Peças & decisões','Datoms & partidas','Engine & infraestrutura','Falhas distribuídas'];
let ledgerCodeFile='ledger.py';
const freshLedgerLab=()=>({journal:[{t:1,key:'opening',kind:'Abertura',entries:[['A',100000],['B',20000],['Clearing',-120000]]}],projectedT:1,asOf:1,message:'Saldos iniciais balanceados: A R$ 1.000, B R$ 200 e clearing −R$ 1.200. Valores fictícios.',tone:'',events:[]});
let ledgerLab=freshLedgerLab();
const ledgerMoney=cents=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(cents/100);
function ledgerBalance(account,t){return ledgerLab.journal.filter(tx=>tx.t<=t).reduce((sum,tx)=>sum+tx.entries.filter(p=>p[0]===account).reduce((s,p)=>s+p[1],0),0)}
function ledgerBlock(b){const heading=b.title?`<h3>${e(b.title)}</h3>`:'';const sources=b.sourceIds?refs(b.sourceIds):'';let body='';if(b.type==='code')body=`<pre class="ledger-code ${b.language==='ascii'?'ascii':''}" tabindex="0"><code>${e(b.text)}</code></pre>`;else if(b.type==='table')body=`<div class="table-wrap"><table><thead><tr>${arr(b.headers).map(h=>`<th>${e(h)}</th>`).join('')}</tr></thead><tbody>${arr(b.rows).map(row=>`<tr>${arr(row).map(c=>`<td>${e(plain(c))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;else if(b.type==='list')body=list(b.items);else if(b.type==='callout')body=`<div class="note ${b.tone==='warning'?'warning':''}">${e(b.text)}</div>`;else body=arr(b.paragraphs||b.text).map(p=>`<p>${e(p)}</p>`).join('');return `<section class="ledger-block">${heading}${body}${sources}</section>`}
function ledgerVisual(){return diagram({id:'ledger-map',title:'Ledger com fronteira transacional e publicação recuperável',nodes:[
{id:'gateway',x:120,y:65,label:'1 App / API Gateway',tech:'envoy',detail:'Autentica, propaga request ID e orçamento de timeout. Envoy/Kong são opções, não evidência de topologia do ledger Nubank. Uma resposta 202 indica aceitação, não liquidação.'},
{id:'redis',x:400,y:65,label:'2 Redis: proteção',tech:'redis',detail:'Rate limit e cache de resultados reduzem trabalho. Expiração/evicção ou failover do Redis não pode liberar um segundo efeito financeiro: a deduplicação definitiva reside na transação do ledger.'},
{id:'account',x:680,y:65,label:'3 Account Service',tech:'clojure',detail:'Valida identidade, contrato e estado da conta. Cache de validação não autoriza gastar saldo antigo; saldo, estado financeiro e idempotência são revalidados na fronteira transacional.'},
{id:'inbound',x:680,y:225,label:'4 Kafka inbound',tech:'kafka',detail:'Comandos duráveis com command ID, tenant, moeda, contas e expected version. Particione pela fronteira de ordenação. O ack do broker não é o commit financeiro. Sobrecarga exige admissão e limite de idade do comando.'},
{id:'core',x:400,y:225,label:'5 Core + transactor',tech:'datomic',detail:'Uma decisão serializada por banco: valida hash de intenção, saldo e todos os lançamentos agregados; grava transação balanceada, resultado e fato de publicação. Reenvio após timeout resolve pelo mesmo ID.'},
{id:'storage',x:120,y:225,label:'6 Storage Datomic',tech:'dynamo',detail:'Variante ilustrada: Datomic Pro com storage DynamoDB suportado. Não editar suas tabelas por fora. Datomic Cloud usa outra topologia AWS, com log em DynamoDB e índices em S3, além de caches.'},
{id:'relay',x:400,y:385,label:'Relay / transaction log',tech:'clojure',detail:'Auxiliar indispensável: lê transações confirmadas ou fatos outbox, publica event ID determinístico e só então avança checkpoint. Se cair após publish e antes do checkpoint, repete; o consumidor deve deduplicar.'},
{id:'outbound',x:680,y:385,label:'7 Kafka outbound',tech:'kafka',detail:'Eventos confirmados: operation ID, event ID, shard/epoch, sequence, schema version e postings. Uma partição dá ordem local; duas partições ou tópicos não fornecem causalidade global.'},
{id:'projector',x:680,y:545,label:'8 Projetores',tech:'clojure',detail:'Aplica evento e registra versão/dedup na mesma operação durável. Um watermark só avança sobre prefixo contínuo confirmado; receber t=12 não prova que t=11 já foi aplicado.'},
{id:'read',x:400,y:545,label:'9 Redis + DynamoDB',tech:'dynamo',detail:'DynamoDB é tabela de projeção; Redis acelera consultas. Não são réplicas transacionais do Datomic. Resposta leva versão aplicada; strong read em DynamoDB não torna novo um evento que ainda não chegou.'},
{id:'status',x:120,y:545,label:'Status / leitura causal',tech:'envoy',detail:'Consulta por operation ID ou leitura com minVersion. Se a projeção não alcançou o token, espera limitada, consulta autoridade ou exibe processando. Nunca apresenta saldo antigo como atual.'}
],edges:[{from:'gateway',to:'redis',label:'request'},{from:'redis',to:'account',label:'admissão'},{from:'account',to:'inbound',label:'command ID'},{from:'inbound',to:'core',label:'replay seguro'},{from:'core',to:'storage',label:'commit durável'},{from:'core',to:'relay',label:'t confirmado'},{from:'relay',to:'outbound',label:'publish / retry'},{from:'outbound',to:'projector',label:'evento + versão'},{from:'projector',to:'read',label:'aplica + checkpoint'},{from:'read',to:'status',label:'saldo + watermark'}]})}
function ledgerExperiment(){const s=ledgerLab,last=s.journal.length,asOf=Math.min(s.asOf,last);return `<section class="panel ledger-experiment" aria-label="Experimento interativo do ledger"><div class="panel-heading"><div><span class="eyebrow">EXPERIMENTE A FRONTEIRA</span><h2>Um commit. Muitas percepções.</h2></div>${chip('MODELO DIDÁTICO','green')}</div><p>Transfira R$ 150, perca a resposta, repita o comando e atrase a projeção. O journal mantém fatos; a tela de leitura só muda quando o projetor avança.</p><div class="ledger-balances"><article><span>Autoridade · t=${last}</span><strong>${ledgerMoney(ledgerBalance('A',last))}</strong><small>Conta A no journal</small></article><article class="${s.projectedT<last?'lagging':''}"><span>Projeção · t=${s.projectedT}</span><strong>${ledgerMoney(ledgerBalance('A',s.projectedT))}</strong><small>${s.projectedT<last?'Desatualizada: não é saldo garantido':'Leitura alcançou o journal'}</small></article><article><span>Contrapartida · conta B</span><strong>${ledgerMoney(ledgerBalance('B',last))}</strong><small>Soma de todos os lançamentos = 0</small></article></div><div class="actions ledger-actions"><button class="button primary" data-ledger-action="transfer">Transferir R$ 150 + perder ACK</button><button class="button" data-ledger-action="retry">Repetir mesma chave</button><button class="button" data-ledger-action="conflict">Mudar valor na mesma chave</button><button class="button" data-ledger-action="project">Avançar projeção</button><button class="button" data-ledger-action="causal">Ler com minVersion</button><button class="button" data-ledger-action="reverse">Adicionar estorno</button><button class="button small" data-ledger-action="reset">Reiniciar laboratório</button></div><div id="ledger-outcome" role="status" class="note ${s.tone}">${e(s.message)}</div><label class="control"><span>Time-travel: saldo da conta A no corte t <strong id="ledger-asof-caption">${asOf} → ${ledgerMoney(ledgerBalance('A',asOf))}</strong></span><input id="ledger-asof" type="range" min="1" max="${last}" value="${asOf}" aria-label="Versão histórica do ledger"></label><div class="table-wrap"><table><thead><tr><th>Tx / intenção</th><th>Δ A</th><th>Δ B</th><th>Δ clearing</th><th>Σ por BRL</th></tr></thead><tbody>${s.journal.map(tx=>`<tr class="${tx.t===asOf?'selected-tx':''}"><td>t=${tx.t} · ${e(tx.kind)}<small class="block">${e(tx.key)}</small></td>${['A','B','Clearing'].map(a=>`<td>${ledgerMoney(tx.entries.filter(p=>p[0]===a).reduce((sum,p)=>sum+p[1],0))}</td>`).join('')}<td>${tx.entries.reduce((sum,p)=>sum+p[1],0)} centavos</td></tr>`).join('')}</tbody></table></div><p class="ledger-caption">Δ é variação do saldo operacional do cliente: positivo aumenta, negativo reduz. No passivo contábil do banco, reduzir o depósito de A é débito; aumentar B é crédito. O laboratório não movimenta dinheiro, não executa o Python nem simula rede real. Reinicia ao recarregar.</p></section>`}
function ledgerAct(action){const s=ledgerLab,original=s.journal.find(tx=>tx.key==='transfer-150');s.tone='';if(action==='reset'){ledgerLab=freshLedgerLab();render(true);return}if(action==='transfer'){if(original){s.message=`A intenção transfer-150 já foi confirmada em t=${original.t}. A chave retorna o mesmo resultado; não há novo lançamento.`;s.tone='success'}else{s.journal.push(Object.freeze({t:s.journal.length+1,key:'transfer-150',kind:'Transferência',entries:Object.freeze([Object.freeze(['A',-15000]),Object.freeze(['B',15000])])}));s.asOf=s.journal.length;s.message='COMMIT t=2 confirmado. ACK perdido: cliente vê timeout, mas os dois lançamentos já existem. Projeção continua em t=1. O resultado financeiro é desconhecido para o cliente, não desfeito.';s.tone='warning'}}else if(action==='retry'){s.message=original?`Replay reconhecido: hash idêntico, resultado original t=${original.t}; journal permanece com ${s.journal.length} transações.`:'Execute a transferência primeiro para criar a intenção durável.';s.tone=original?'success':''}else if(action==='conflict'){s.message=original?'CONFLITO: transfer-150 já pertence a R$ 150,00. Tentar R$ 100,00 com a mesma chave falha antes de qualquer efeito. Não retorne sucesso silencioso nem substitua o payload.':'Execute a transferência primeiro. Uma chave inexistente ainda não está associada a uma intenção.';s.tone='warning'}else if(action==='project'){s.projectedT=s.journal.length;s.message=`Projetor aplicou todos os eventos até t=${s.projectedT}, em ordem contínua; dados e watermark foram confirmados juntos no modelo.`;s.tone='success'}else if(action==='causal'){const token=original?s.journal.length:1;s.message=s.projectedT>=token?`minVersion=${token} atendida: saldo A ${ledgerMoney(ledgerBalance('A',s.projectedT))} na versão ${s.projectedT}.`:`minVersion=${token}, projeção=${s.projectedT}: a leitura não atende a sessão. Espera limitada ou retorno 'processando'; fallback autoritativo retornaria ${ledgerMoney(ledgerBalance('A',s.journal.length))}. Um GET fortemente consistente da tabela atrasada não resolve o lag.`;s.tone=s.projectedT>=token?'success':'warning'}else if(action==='reverse'){if(!original)s.message='Não existe transferência para estornar. Crie a operação original primeiro.';else if(s.journal.some(tx=>tx.key==='reversal-transfer-150')){s.message='O estorno já existe. O vínculo único reversal-of impede compensação duplicada.';s.tone='success'}else{s.journal.push(Object.freeze({t:s.journal.length+1,key:'reversal-transfer-150',kind:'Estorno de t=2',entries:Object.freeze(original.entries.map(([a,v])=>Object.freeze([a,-v])))}));s.asOf=s.journal.length;s.message='Novo commit de estorno com sinais opostos. t=2 permanece intacto; as-of t=2 ainda mostra R$ 850 em A. A projeção pode continuar atrasada. Neste exemplo B conserva recursos; em produção, bloqueios, overdraft e reconciliação precisam de política explícita.';s.tone='success'}}render(true)}
function ledgerCode(){const files=D.ledger.codeFiles||[],file=files.find(f=>f.name===ledgerCodeFile)||files[0];if(!file)return '';return `<section class="panel ledger-source"><div class="panel-heading"><div><span class="eyebrow">CÓDIGO COMPLETO · EXECUTÁVEL</span><h2>Examine, rode e quebre os invariantes.</h2></div><a class="button small" href="https://github.com/wesleyvieira99/nuArch/tree/main/examples/ledger" target="_blank" rel="noopener">Ver no GitHub ↗</a></div><p>Implementação de referência em memória, com testes de isolamento entre threads. Um lock local e estruturas frozen não fornecem durabilidade, consenso entre processos ou uma plataforma bancária pronta para produção. O capítulo detalha o que a versão persistente precisa garantir.</p><div class="tabs" role="tablist" aria-label="Arquivos do exemplo">${files.map(f=>`<button class="tab ${file.name===f.name?'active':''}" role="tab" aria-selected="${file.name===f.name}" data-ledger-file="${e(f.name)}">${e(f.name)}</button>`).join('')}</div><div class="actions"><button class="button small" id="ledger-copy-code">Copiar arquivo</button><button class="button small" id="ledger-download-code">Baixar arquivo</button><span class="ledger-caption">${file.text.split('\n').length} linhas · ${e(file.language||'texto')}</span></div><pre class="ledger-code source-file" tabindex="0"><code>${e(file.text)}</code></pre></section>`}
function ledgerPage(id){const n=Math.max(1,Math.min(5,parseInt(id,10)||1)),chapter=D.ledger.sections[n-1];return `${title('ENGENHARIA FINANCEIRA · DE PONTA A PONTA','Ledger bancário imutável','Do invariante contábil ao commit durável: cinco capítulos para explicar as decisões, implementar o núcleo e enfrentar falhas.')}<div class="ledger-intro panel"><div><span class="eyebrow">LEITURA EM PROFUNDIDADE</span><h2>O dinheiro exige uma história coerente.</h2><p>${e(D.ledger.scope||'Arquitetura de referência inspirada em fontes públicas. Não é uma reprodução confirmada do ledger interno do Nubank.')}</p></div><div class="ledger-intro-symbol" aria-hidden="true"><span>Σ</span><small>lançamentos assinados</small><b>= 0</b><small>por moeda</small></div></div><nav class="ledger-nav" aria-label="Seções do ledger">${ledgerSections.map((s,i)=>`<a href="#ledger/${i+1}" class="${n===i+1?'active':''}" ${n===i+1?'aria-current="page"':''}><span>0${i+1}</span>${s}</a>`).join('')}</nav><article class="reading ledger-reading"><div class="ledger-heading"><span class="eyebrow">SEÇÃO 0${n} / 05</span><h2>${e(chapter.title)}</h2>${chapter.intro?`<p>${e(chapter.intro)}</p>`:''}</div>${n===1?`<section class="panel"><h3>Inspecione o caminho de uma operação</h3><p>Clique em cada peça. O relay torna recuperável a fronteira entre banco e eventos; o token de leitura torna explícito o atraso da projeção.</p>${ledgerVisual()}</section>`:''}${n===3?ledgerExperiment():''}${n===4?ledgerCode():''}<section class="panel ledger-prose">${chapter.blocks.map(ledgerBlock).join('')}</section>${refs(chapter.sourceIds)}<div class="ledger-pagination">${n>1?`<a class="button" href="#ledger/${n-1}">← ${ledgerSections[n-2]}</a>`:'<a class="button" href="#atlas/ledger">Consultar padrão no atlas ↗</a>'}${n<5?`<a class="button primary" href="#ledger/${n+1}">${ledgerSections[n]} →</a>`:'<a class="button primary" href="#questions?q=ledger">Defender em perguntas →</a>'}</div></article>`}
function bindLedger(){$$('[data-ledger-action]').forEach(b=>b.onclick=()=>ledgerAct(b.dataset.ledgerAction));$$('[data-ledger-file]').forEach(b=>b.onclick=()=>{ledgerCodeFile=b.dataset.ledgerFile;render(true)});if($('#ledger-asof'))$('#ledger-asof').oninput=()=>{ledgerLab.asOf=+$('#ledger-asof').value;$('#ledger-asof-caption').textContent=`${ledgerLab.asOf} → ${ledgerMoney(ledgerBalance('A',ledgerLab.asOf))}`;$$('.ledger-experiment tbody tr').forEach((row,i)=>row.classList.toggle('selected-tx',i+1===ledgerLab.asOf))};const file=(D.ledger?.codeFiles||[]).find(f=>f.name===ledgerCodeFile)||(D.ledger?.codeFiles||[])[0];if($('#ledger-copy-code'))$('#ledger-copy-code').onclick=async()=>{try{await navigator.clipboard.writeText(file.text);toast('Arquivo copiado')}catch{toast('Selecione o código e use Copiar. A área de transferência está indisponível.')}};if($('#ledger-download-code'))$('#ledger-download-code').onclick=()=>{const url=URL.createObjectURL(new Blob([file.text],{type:'text/plain;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}


const foundationNames={cap:'CAP & consistência',replication:'Replicação & sharding',databases:'Bancos & índices',caches:'Caches',balancing:'Balanceamento',queues:'Filas & backpressure'};
const foundationDescriptions={cap:'O limite que aparece quando a rede deixa de conectar todas as partes.',replication:'Cópias, maiorias, propriedade dos dados e a conta quente.',databases:'Modelos de dados, páginas de índice, WAL, lag e sessões.',caches:'Memória finita, validade da informação e trabalho duplicado.',balancing:'Distribuir tráfego, preservar capacidade e controlar rajadas.',queues:'Aceitar trabalho é assumir prazo, memória e recuperação.'};
let capState={partition:false,written:false,policy:'consistent',message:'Todos os nós começam com x=1000. Primeiro isole a réplica C.'};
function foundationDiagram(id){const make=(nodes,edges,title)=>({id:`fund-${id}`,title,nodes:nodes.map(([nid,label,x,y,tech,detail])=>({id:nid,label,x,y,tech,detail})),edges:edges.map(([from,to,label])=>({from,to,label}))});
const maps={
cap:make([
 ['client','Cliente / ordem real',120,65,'envoy','A leitura começa depois que a escrita já respondeu sucesso. Esse vínculo de tempo real é o que a linearizabilidade precisa respeitar.'],
 ['a','Réplica A · líder',400,65,'postgres','A e B permanecem conectadas. Em um protocolo apropriado, a maioria pode confirmar uma escrita sem aguardar C. Isso não torna qualquer regra de R/W um protocolo de consenso.'],
 ['b','Réplica B · maioria',680,65,'postgres','Uma cópia elegível confirma conforme a semântica de persistência e replay do protocolo. Receber bytes não é necessariamente poder atender uma leitura atual.'],
 ['c','Réplica C · isolada',400,255,'postgres','C continua executando, mas não recebe mensagens da maioria. Responder com x antigo preserva a resposta local e pode violar linearizabilidade. Recusar/esperar não atende a disponibilidade formal CAP para essa operação.'],
 ['reader','Leitor do outro lado',120,255,'envoy','Timeout não distingue servidor morto de rede lenta. Clientes e operações podem ter políticas diferentes, mas o contrato declarado precisa informar o que cada resposta significa.']
],[['client','a','write x=850'],['a','b','replica / confirma'],['a','c','fronteira de rede'],['reader','c','read depois do ACK']],'CAP: duas visões da mesma história'),
replication:make([
 ['router','Roteador / epoch',120,65,'envoy','Resolve a chave para a autoridade atual. A versão de ownership ajuda a rejeitar escritores antigos durante migração.'],
 ['leader','Shard 1 · líder',400,65,'postgres','Ordena commits locais. Uma conta quente não é dividida automaticamente pela adição de shards.'],
 ['follower','Shard 1 · seguidor',680,65,'postgres','Recebe, persiste e aplica log em etapas distintas. Fallback para ele precisa de contrato de frescor e de promoção segura.'],
 ['other','Shard 2 · líder',400,255,'postgres','Outro grupo possui sua própria história. Transferência entre grupos exige coordenação, protocolo distribuído ou workflow com estados intermediários explícitos.'],
 ['migration','Backfill + catch-up',680,255,'kafka','Copiar o estado inicial não inclui escritas concorrentes automaticamente. Catch-up, barreira de corte, roteamento versionado e fencing completam uma migração correta.']
],[['router','leader','chave / grupo'],['leader','follower','WAL / log'],['router','other','outra chave'],['leader','other','fronteira transacional'],['follower','migration','posição aplicada']],'Replicação copia; sharding divide a autoridade'),
databases:make([
 ['pool','Pool limitado',120,65,'postgres','Fila de aquisição separada do tempo de query. Mais conexões multiplicam backends, memória, contenção e context switches.'],
 ['planner','Planner + índice',400,65,'postgres','Estatísticas, seletividade e correlação orientam plano. Índice composto, parcial ou covering resolve um access pattern ao preço de mais escrita e espaço.'],
 ['heap','Páginas / MVCC',680,65,'postgres','O índice aponta para versões que ainda podem exigir heap fetch e teste de visibilidade. Longas transações retêm versões e atrasam limpeza.'],
 ['wal','WAL + persistência',400,255,'postgres','O commit espera a condição de durabilidade configurada. fsync e group commit tratam persistência; locks e isolamento tratam outras propriedades.'],
 ['replica','Réplica / replay',680,255,'postgres','Receive, flush e replay têm posições distintas. Redirecionar a query para uma réplica muda o contrato, não só o host.']
],[['pool','planner','query'],['planner','heap','busca / scan'],['planner','wal','write + índices'],['wal','replica','replicação'],['heap','replica','visão pode divergir']],'Do pedido SQL ao custo físico'),
caches:make([
 ['traffic','Leitores concorrentes',120,65,'envoy','Uma chave quente expira e milhares de requests chegam juntos. Não confundir esse miss simultâneo com uma chave inexistente atacada repetidamente.'],
 ['cache','Cache / TTL / versão',400,65,'redis','Evicção libera espaço; expiração limita validade por tempo. Nenhuma delas prova que o valor de origem não mudou.'],
 ['origin','Origem autoritativa',680,65,'postgres','Um miss vira trabalho real: CPU, I/O, locks e conexões. A capacidade da origem precisa sobreviver à perda do cache com admissão e degradação.'],
 ['coalesce','Singleflight / lease',400,255,'redis','Coalescer local reduz duplicatas só por processo. Coordenação entre processos exige lease, dono, expiração, fencing e prevenção de escritor atrasado.'],
 ['stale','Snapshot permitido',120,255,'redis','Stale-while-revalidate pode atender conteúdo informativo dentro de janela explícita. Autorização e saldo gastável não devem depender de uma cópia tolerante a atraso.']
],[['traffic','cache','get(k)'],['cache','origin','miss sem proteção'],['cache','coalesce','eleger refresh'],['coalesce','origin','fetch limitado'],['cache','stale','degradação contratada']],'Um miss não precisa virar mil consultas'),
balancing:make([
 ['admit','Admissão / orçamento',120,65,'envoy','Controla taxa, rajadas e concorrência antes de gastar trabalho caro. Retries devem respeitar o mesmo orçamento e deadline.'],
 ['lb','Balanceador L4 / L7',400,65,'envoy','Algoritmo usa informação incompleta: conexões, requests, latência ou hash. Um stream longo e uma query curta não custam o mesmo.'],
 ['a','Backend A',680,65,'k8s','Health e readiness precisam refletir capacidade. Uma instância lenta ainda pode responder ao health check e prejudicar p99.'],
 ['b','Backend B / drain',680,255,'k8s','Drain encerra a admissão de novos fluxos e permite concluir os existentes dentro de um prazo. Conexão não é unidade equivalente a request em HTTP/2.'],
 ['state','Sessão / estado',400,255,'redis','Afinidade é preferência de roteamento, não replicação. Se o nó morre, uma sessão só sobrevive se o estado e sua política de consistência permitirem.']
],[['admit','lb','aceita / rejeita'],['lb','a','seleção'],['lb','b','seleção / drain'],['lb','state','afinidade'],['b','state','estado compartilhado']],'Balancear e limitar são decisões diferentes'),
queues:make([
 ['producer','Produtor / outbox',120,65,'postgres','O pedido aceito precisa de uma intenção recuperável. Se o buffer enche, rejeite, reduza admissão ou persista sob contrato explícito; RAM ilimitada não existe.'],
 ['broker','Broker / buffer finito',400,65,'kafka','A fila desacopla tempos até seus limites de retenção, memória e disco. Idade do item mais antigo revela atraso que throughput médio esconde.'],
 ['consumer','Consumidor / crédito',680,65,'clojure','Limita trabalho in-flight conforme capacidade do destino. Pause, poll, heartbeats, visibility timeout e acknowledgment dependem do produto.'],
 ['effect','Efeito + inbox',680,255,'postgres','Confirma dedupe e efeito na mesma transação local quando possível. Só depois avança ack/checkpoint. Queda nessa fronteira causa reentrega esperada.'],
 ['dlq','Retry / quarentena',400,255,'kafka','Separar poison message evita tempestade, mas pular a mensagem pode romper ordem causal. Recuperar precisa de owner, motivo, versão e replay controlado.']
],[['producer','broker','publicação durável'],['broker','consumer','entrega / crédito'],['consumer','effect','efeito local'],['effect','broker','ack após commit'],['consumer','dlq','falha classificada'],['dlq','broker','replay autorizado']],'Fila estável exige controle de entrada e saída')
};return diagram(maps[id]);}
function foundationPage(id){const chapters=D.foundations.chapters,c=chapters.find(x=>x.id===id)||chapters[0],index=chapters.indexOf(c);return `${title('MECANISMOS · LIMITES · DECISÕES','Fundamentos distribuídos','Por dentro das garantias e dos gargalos: teoria, algoritmo, armazenamento, rede, recuperação e experiência do usuário.')}<nav class="foundation-nav" aria-label="Capítulos de fundamentos">${chapters.map((x,i)=>`<a href="#foundations/${e(x.id)}" class="${x.id===c.id?'active':''}" ${x.id===c.id?'aria-current="page"':''}><b>0${i+1}</b><span>${e(foundationNames[x.id])}</span></a>`).join('')}</nav><section class="foundation-hero panel"><div><span class="eyebrow">CAPÍTULO 0${index+1} / 06</span><h2>${e(c.title)}</h2><p>${e(c.summary||c.subtitle)}</p></div><div class="foundation-hero-tag">${icon({cap:'layers',replication:'atlas',databases:'code',caches:'lab',balancing:'arrow',queues:'mocks'}[c.id])}<span>${e(foundationDescriptions[c.id])}</span></div></section><div class="reading foundation-reading"><section class="panel"><h2>Veja a fronteira antes de escolher a tecnologia.</h2>${foundationDiagram(c.id)}</section>${foundationLab(c.id)}<section class="panel foundation-toc"><h3>Dentro deste capítulo</h3><div>${c.sections.map((s,i)=>`<button data-section-jump="${i}"><span>${String(i+1).padStart(2,'0')}</span>${e(s.title)} ↓</button>`).join('')}</div></section>${c.sections.map((s,i)=>`<section class="panel foundation-section" tabindex="-1" id="foundation-section-${i}"><div class="foundation-section-heading"><span>${String(i+1).padStart(2,'0')}</span><h2>${e(s.title)}</h2></div>${s.blocks.map(ledgerBlock).join('')}</section>`).join('')}<section class="panel"><span class="eyebrow">DEFENDA AS DECISÕES</span><h2>Pratique como uma pessoa Staff.</h2><div class="questions">${c.questions.map((q,i)=>`<details class="question"><summary><span class="q-number">${String(i+1).padStart(2,'0')}</span><span class="q-title">${e(q.q)}</span></summary><div class="question-body">${arr(q.answer).map(p=>`<p>${e(p)}</p>`).join('')}</div></details>`).join('')}</div></section>${refs(c.sourceIds)}<div class="ledger-pagination">${index?`<a class="button" href="#foundations/${chapters[index-1].id}">← ${e(foundationNames[chapters[index-1].id])}</a>`:'<a class="button" href="#atlas">Explorar arquiteturas ↗</a>'}${index<chapters.length-1?`<a class="button primary" href="#foundations/${chapters[index+1].id}">${e(foundationNames[chapters[index+1].id])} →</a>`:'<a class="button primary" href="#mocks">Testar em um simulado →</a>'}</div></div>`}
function foundationInput(id,label,min,max,value,unit='',step=1){return `<label class="control"><span>${label}<strong id="${id}-value">${value} ${unit}</strong></span><input data-foundation-input type="range" id="${id}" min="${min}" max="${max}" step="${step}" value="${value}" data-unit="${unit}" aria-label="${label}"></label>`}
function foundationLab(id){const head=(tag,h)=>`<div class="panel-heading"><div><span class="eyebrow">${tag}</span><h2>${h}</h2></div>${chip('EXPERIMENTO DIDÁTICO','green')}</div>`;
if(id==='cap')return `<section class="panel" id="cap-experiment">${head('CAP · UM CONTRAEXEMPLO','Uma resposta rápida pode contar uma história antiga.')}<p>Três réplicas de um único registro x. A e B formam o lado majoritário; C pode ficar isolada. A leitura de C acontece depois do ACK de uma escrita confirmada em A/B.</p><div class="cap-cluster"><div><span>A + B</span><strong>x = ${capState.written?850:1000}</strong><small>lado que confirma a escrita</small></div><div class="cap-link ${capState.partition?'broken':''}">${capState.partition?'× partição':'↔ rede conectada'}</div><div><span>C</span><strong>x = ${capState.written&&!capState.partition?850:1000}</strong><small>${capState.partition?'não recebe a nova versão':'réplica sincronizada no modelo'}</small></div></div><div class="actions"><button class="button" data-cap="partition">Isolar C</button><button class="button primary" data-cap="write">Confirmar x=850 em A/B</button><button class="button" data-cap="read">Ler em C após o ACK</button><button class="button" data-cap="heal">Restabelecer e sincronizar</button><button class="button small" data-cap="reset">Reiniciar</button></div><label class="foundation-select">Política de leitura em C <select id="cap-policy"><option value="consistent" ${capState.policy==='consistent'?'selected':''}>Exigir leitura linearizável</option><option value="local" ${capState.policy==='local'?'selected':''}>Permitir cópia local atrasada</option></select></label><div class="note" role="status" id="cap-outcome">${e(capState.message)}</div><p class="foundation-caption">A disponibilidade de CAP é uma propriedade formal: uma resposta de erro não equivale a completar corretamente qualquer operação. A simulação supõe um protocolo que confirma a escrita na maioria; não implementa consenso, relógios, eleição ou recovery. Nenhum dinheiro é movimentado.</p></section>`;
if(id==='replication')return `<section class="panel">${head('QUORUM · CONTAGEM NÃO É PROTOCOLO','Quantos nós precisam responder?')}<div class="two-col"><div><label class="foundation-select">Réplicas N <select id="quorum-n"><option>3</option><option>5</option><option>7</option></select></label>${foundationInput('quorum-r','Respostas exigidas na leitura R',1,3,2,'nós')}${foundationInput('quorum-w','Confirmações exigidas na escrita W',1,3,2,'nós')}<p>Selecione os nós alcançáveis pelo coordenador. Todos pertencem ao mesmo conjunto fixo de réplicas.</p><div id="quorum-nodes" class="quorum-nodes"></div></div><div id="quorum-result" aria-live="polite"></div></div><p class="foundation-caption">Interseção de conjuntos não garante linearizabilidade sozinha: faltam versão/ordenação, tratamento de concorrência, leitura correta, mudança de membership e recuperação. Sloppy quorums, réplicas adicionais ou ack antes da persistência mudam as premissas. O laboratório calcula apenas alcançabilidade e interseção.</p></section>`;
if(id==='databases')return `<section class="panel">${head('POOL · DEMANDA POR SESSÕES','Um pool maior também custa ao banco.')}<div class="two-col"><div>${foundationInput('pool-arrival','Chegadas ao banco',50,5000,800,'queries/s',50)}${foundationInput('pool-service','Tempo médio segurando conexão',5,200,40,'ms',5)}${foundationInput('pool-size','Conexões disponíveis',1,200,40,'conexões')}<p>Inclua no tempo de ocupação toda transação, espera e I/O que segura a sessão. Não substitua a média pelo p99 na Lei de Little.</p></div><div id="pool-result" aria-live="polite"></div></div><p class="foundation-caption">Modelo com tempo de serviço fixo e capacidade proporcional ao pool. Bancos reais podem piorar com mais concorrência por CPU, locks, cache e I/O. A estimativa não dimensiona produção nem calcula latência de fila.</p></section>`;
if(id==='caches')return `<section class="panel">${head('CACHE · UMA CHAVE QUENTE','Quantas consultas um único miss provoca?')}<div class="two-col"><div>${foundationInput('cache-burst','Pedidos simultâneos para a mesma chave',10,5000,1000,'pedidos',10)}${foundationInput('cache-instances','Instâncias da aplicação',1,100,10,'instâncias')}<label class="foundation-select">Proteção de refresh <select id="cache-policy"><option value="none">Sem coalescing</option><option value="local">Singleflight por instância</option><option value="coordinated">Coordenação global idealizada</option></select></label></div><div id="cache-burst-result" aria-live="polite"></div></div><p class="foundation-caption">O burst ocorre antes de qualquer fetch terminar. Com distribuição balanceada, cada instância ocupada elege um fetch local. A opção global supõe coordenação perfeita, sem lease expirando, crash ou atraso: a implementação real precisa tratar essas falhas. Redução de fetches não representa redução garantida de p99.</p></section>`;
if(id==='balancing')return `<section class="panel">${head('ADMISSÃO · TOKEN BUCKET','Ritmo sustentado e rajada são limites diferentes.')}<div class="two-col"><div>${foundationInput('bucket-rate','Reposição de tokens',10,1000,100,'por segundo',10)}${foundationInput('bucket-size','Capacidade do bucket',10,2000,200,'tokens',10)}${foundationInput('bucket-burst','Rajada no instante zero',10,3000,600,'pedidos',10)}${foundationInput('bucket-steady','Pedidos nos segundos seguintes',10,1500,150,'por segundo',10)}</div><div><div id="bucket-result" aria-live="polite"></div><div class="table-wrap"><table id="bucket-table"><thead><tr><th>t (s)</th><th>Aceitos</th><th>Rejeitados</th><th>Tokens restantes</th></tr></thead><tbody></tbody></table></div></div></div><p class="foundation-caption">Modelo discreto: bucket começa cheio, repõe tokens e recebe um lote por segundo. Token por pedido de custo uniforme. Os excedentes são rejeitados, não enfileirados: é policing/admissão. Shaping com espera exige buffer e deadline. Rate limit não limita sozinho o número de requests em execução.</p></section>`;
return `<section class="panel">${head('BACKPRESSURE · BUFFER LIMITADO','A fila compra tempo. Não cria capacidade.')}<div class="two-col"><div>${foundationInput('queue-arrival','Taxa de chegada',100,10000,3000,'mensagens/s',100)}${foundationInput('queue-workers','Consumidores efetivos',0,32,8,'workers')}${foundationInput('queue-service','Serviço médio por mensagem',1,50,5,'ms')}${foundationInput('queue-buffer','Capacidade da fila',100,100000,10000,'mensagens',100)}${foundationInput('queue-window','Duração da janela',1,120,20,'segundos')}</div><div id="queue-result" aria-live="polite"></div></div><p class="foundation-caption">Modelo fluido de uma janela que começa vazia, com taxas constantes e workers independentes. Excedentes ao buffer são rejeitados na admissão. Não modela retrabalho, distribuição dos tempos, mensagens in-flight, batching ou partições quentes. Drenagem assume chegada zero; não é o tempo de recuperar atraso com tráfego continuando.</p></section>`;}
let quorumReachable=[true,true,true];
const foundationMetric=(n,label)=>`<div class="foundation-metric"><strong>${n}</strong><span>${label}</span></div>`;
function foundationNumbers(){const val=id=>Number($(`#${id}`).value);if($('#quorum-n')){const n=val('quorum-n'),r=val('quorum-r'),w=val('quorum-w'),reachable=quorumReachable.filter(Boolean).length,m=quorumModel(n,r,w,reachable);$('#quorum-result').innerHTML=`${foundationMetric(`${reachable}/${n}`,'réplicas alcançáveis deste lado')}<div class="note ${m.read&&m.write?'success':'warning'}"><strong>Leitura:</strong> ${m.read?'há respostas suficientes':'não há respostas suficientes'}<br><strong>Escrita:</strong> ${m.write?'há confirmações suficientes':'não há confirmações suficientes'}</div><p>R + W = ${r+w}; interseção mínima entre um quorum de leitura e um de escrita: <strong>${m.readWriteIntersection}</strong>. Entre dois quorums de escrita: <strong>${m.writeWriteIntersection}</strong>.</p><p>Indisponibilidade tolerada pela contagem: até ${m.readFailures} nós para leitura; ${m.writeFailures} para escrita. O protocolo pode exigir restrições adicionais.</p>`}
if($('#pool-arrival')){const m=poolModel(val('pool-arrival'),val('pool-service'),val('pool-size'));$('#pool-result').innerHTML=`${foundationMetric(m.offered.toFixed(1),'conexões ocupadas em média: λ × tempo de ocupação')}${foundationMetric(`${(m.utilization*100).toFixed(1)}%`,'carga oferecida / capacidade do pool')}<div class="note ${m.stable?'':'warning'}">${m.stable?'Há margem de capacidade no modelo; variabilidade ainda gera espera.':'Não existe equilíbrio com margem: a fila cresce quando a carga excede a capacidade; igualdade também não absorve variação.'}</div><p>Capacidade ideal: ${fmt(Math.round(m.capacity))} queries/s. O orçamento total precisa considerar todas as réplicas da aplicação e conexões reservadas para operação.</p>`}
if($('#cache-burst')){const m=cacheBurstModel(val('cache-burst'),val('cache-instances'),$('#cache-policy').value);$('#cache-burst-result').innerHTML=`${foundationMetric(fmt(m.fetches),'fetches simultâneos na origem')}${foundationMetric(fmt(m.followers),'pedidos que compartilham um fetch')}<div class="note">Redução modelada de consultas: ${(100*m.reduction).toFixed(1)}%. Os seguidores ainda precisam de limite de espera, cancelamento e tratamento da falha de quem está fazendo o refresh.</div>`}
if($('#bucket-rate')){const rows=tokenBucketModel(val('bucket-rate'),val('bucket-size'),val('bucket-burst'),val('bucket-steady')),accepted=rows.reduce((s,r)=>s+r.accepted,0),rejected=rows.reduce((s,r)=>s+r.rejected,0);$('#bucket-result').innerHTML=`${foundationMetric(fmt(accepted),'pedidos aceitos entre t=0 e t=10 s')}<p>${fmt(rejected)} rejeitados no período. Um bucket cheio permite uma rajada maior que a taxa sustentada.</p>`;$('#bucket-table tbody').innerHTML=rows.map(r=>`<tr><td>${r.t}</td><td>${r.accepted}</td><td>${r.rejected}</td><td>${r.tokens}</td></tr>`).join('')}
if($('#queue-arrival')){const m=queueModel(val('queue-arrival'),val('queue-workers'),val('queue-service'),val('queue-buffer'),val('queue-window'));$('#queue-result').innerHTML=`${foundationMetric(fmt(Math.round(m.serviceRate)),'mensagens/s de capacidade ideal')}${foundationMetric(fmt(Math.round(m.queued)),'mensagens acumuladas ao final')}${foundationMetric(fmt(Math.round(m.rejected)),'mensagens rejeitadas na admissão')}<div class="note ${m.stable?'success':'warning'}">${m.stable?'Capacidade acima da chegada neste modelo.':m.serviceRate===val('queue-arrival')?'Chegada igual à capacidade: zero acúmulo no modelo ideal, mas nenhuma margem para variabilidade.':m.fillSeconds<=val('queue-window')?`Buffer esgota em ${m.fillSeconds.toFixed(2)} s; continuar aceitando sem limite apenas deslocaria a falha.`:'A fila acumula; esta janela ainda não esgotou o buffer.'}</div><p>Drenagem sem novas chegadas: ${Number.isFinite(m.drainSeconds)?m.drainSeconds.toFixed(2)+' s':'impossível enquanto consumidores não recuperarem capacidade'}. λ = μ deixa margem zero para variabilidade.</p>`}}
function bindFoundations(){$$('[data-section-jump]').forEach(b=>b.onclick=()=>{const section=$(`#foundation-section-${b.dataset.sectionJump}`);section?.focus({preventScroll:true});section?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth',block:'start'})});$$('[data-foundation-input]').forEach(input=>input.oninput=()=>{$(`#${input.id}-value`).textContent=`${input.value} ${input.dataset.unit}`;foundationNumbers()});for(const id of ['cache-policy'])if($(`#${id}`))$(`#${id}`).onchange=foundationNumbers;if($('#quorum-n')){const nodes=()=>{$('#quorum-nodes').innerHTML=quorumReachable.map((yes,i)=>`<button class="${yes?'reachable':''}" data-quorum-node="${i}" aria-pressed="${yes}"><span>${yes?'●':'○'}</span>R${i+1}<small>${yes?'alcançável':'isolada'}</small></button>`).join('');$$('[data-quorum-node]').forEach(b=>b.onclick=()=>{const index=+b.dataset.quorumNode;quorumReachable[index]=!quorumReachable[index];nodes();foundationNumbers();$(`[data-quorum-node="${index}"]`)?.focus({preventScroll:true})})};$('#quorum-n').onchange=()=>{const n=+$('#quorum-n').value;quorumReachable=Array(n).fill(true);for(const key of ['r','w']){const input=$(`#quorum-${key}`);input.max=n;input.value=Math.ceil(n/2);$(`#quorum-${key}-value`).textContent=`${input.value} nós`}nodes();foundationNumbers()};quorumReachable=Array(3).fill(true);nodes()}
$$('[data-cap]').forEach(b=>b.onclick=()=>{const s=capState;switch(b.dataset.cap){case'partition':s.partition=true;s.written=false;s.message='Novo experimento: C isolada; todas as réplicas começam com x=1000. Confirme uma escrita em A/B.';break;case'write':s.written=true;s.message=s.partition?'Escrita x=850 concluída em A/B. O cliente recebeu ACK; C não recebeu a atualização. Agora a leitura inicia depois desse ACK.':'Escrita x=850 concluída e C sincronizada no modelo sem partição.';break;case'read':s.message=!s.written?'Ainda não houve escrita. Para demonstrar a contradição, confirme x=850 antes da leitura.':!s.partition?'Leitura retorna x=850: a versão escrita já está em C.':s.policy==='consistent'?'C não consegue provar a versão atual nem contatar a autoridade. Espera/erro preserva a exigência de linearizabilidade, mas esta operação não completa com a disponibilidade formal de CAP.':'C responde x=1000 depois do ACK de x=850. A operação responde localmente, mas este histórico viola linearizabilidade. Consistência eventual pode convergir após a rede recuperar.';break;case'heal':s.partition=false;s.message='Rede restabelecida e réplica C atualizada no modelo. Recuperar a rede não reescreve a resposta antiga que um cliente já observou.';break;case'reset':capState={partition:false,written:false,policy:'consistent',message:'Todos os nós começam com x=1000. Primeiro isole a réplica C.'}}render(true)});if($('#cap-policy'))$('#cap-policy').onchange=()=>{capState.policy=$('#cap-policy').value};foundationNumbers();}
function operationsView(a){const o=a.operations;if(!o)return '<div class="note">Análise operacional indisponível.</div>';return `<section class="panel"><span class="eyebrow">DIAGNÓSTICO ANTES DA MUDANÇA</span><h2>Onde este desenho encontra seu limite?</h2><p>Os sinais abaixo orientam hipóteses e testes. Metas de serviço são propostas para o exercício e precisam de orçamento end-to-end; não representam SLAs internos do Nubank.</p><div class="two-col">${o.bottlenecks.map(b=>`<article class="operations-card"><h3>${e(b.where)}</h3><dl><dt>Observe</dt><dd>${e(b.signal)}</dd><dt>Mecanismo do gargalo</dt><dd>${e(b.cause)}</dd><dt>Como aliviar</dt><dd>${e(b.mitigation)}</dd><dt>O preço da mudança</dt><dd>${e(b.tradeoff)}</dd></dl></article>`).join('')}</div></section><section class="panel"><span class="eyebrow">EVOLUÇÃO COM CRITÉRIO</span><h2>Como escalar sem perder a invariante</h2><p><strong>Gatilho para agir:</strong> ${e(o.scaling.trigger)}</p><ol class="scaling-steps">${o.scaling.sequence.map((s,i)=>`<li><span>0${i+1}</span><p>${e(s)}</p></li>`).join('')}</ol><div class="note"><strong>Limite que continua existindo:</strong> ${e(o.scaling.limit)}</div></section><section class="panel"><span class="eyebrow">FALHA → RESPOSTA → RECUPERAÇÃO</span><h2>O que acontece quando uma peça deixa de funcionar?</h2>${o.resilience.map((r,i)=>`<article class="failure-scenario"><h3>${String(i+1).padStart(2,'0')} · ${e(r.failure)}</h3><div class="failure-flow"><span>Detectar</span><i>→</i><span>Conter / failover</span><i>→</i><span>Recuperar / reconciliar</span></div><div class="two-col"><dl><dt>Sinal e detecção</dt><dd>${e(r.detection)}</dd><dt>Failover e contenção</dt><dd>${e(r.failover)}</dd><dt>Retorno ao serviço</dt><dd>${e(r.recovery)}</dd></dl><dl><dt>O que a pessoa percebe</dt><dd>${e(r.userImpact)}</dd><dt>Risco sobre estado e dinheiro</dt><dd>${e(r.dataRisk)}</dd></dl></div></article>`).join('')}</section><section class="panel"><span class="eyebrow">DO COMPONENTE À JORNADA</span><h2>Experiência, SLI, SLO e compromisso de serviço</h2><dl class="service-contract">${Object.entries({userJourney:'Jornada observada',sli:'Como medir — SLI',slo:'Objetivo proposto — SLO',timeoutPolicy:'Deadline e degradação',recoveryObjectives:'Recuperação — RTO e RPO',validation:'Como demonstrar a garantia'}).map(([k,l])=>`<div><dt>${l}</dt><dd>${e(o.serviceLevel[k])}</dd></div>`).join('')}</dl><div class="note">SLA é um compromisso contratual, frequentemente com exclusões e consequências. SLO é o objetivo técnico; SLI é a medida. Um failover pode restaurar disponibilidade e ainda violar frescor, prazo ou durabilidade da jornada.</div></section><section class="panel"><span class="eyebrow">DEFESA STAFF</span><h2>${e(o.staffQuestion.question)}</h2><p>${e(o.staffQuestion.answer)}</p>${refs(o.sourceIds||a.sourceIds)}</section>`}

// Videos load one third-party player only after an explicit click.
let videoKind='',videoChannel='';
function videoDuration(seconds){const h=Math.floor(seconds/3600),m=Math.floor(seconds%3600/60);return `${h?h+' h ':''}${m} min`}
function videoCard(v,index){const done=progress.checks.includes(`video:${v.id}`);return `<article class="video-card ${currentId===v.id?'selected':''}"><a class="video-thumb" href="#videos/${e(v.id)}" aria-label="Abrir estudo: ${e(v.title)}"><img src="${e(v.thumbnail)}" alt="Miniatura do vídeo ${e(v.title)}" loading="lazy" width="480" height="360"><span class="video-play" aria-hidden="true">▶</span><span class="video-time">${e(v.duration)}</span></a><div class="video-card-body"><div class="actions">${chip(v.kind)}${chip(v.topic,'neutral')}</div><span class="video-author">${String(index+1).padStart(2,'0')} · ${e(v.channel)}</span><h3><a href="#videos/${e(v.id)}">${e(v.title)}</a></h3><p>${e(v.guide)}</p><div class="video-card-actions"><a class="button small" href="#videos/${e(v.id)}">Estudar este vídeo ↗</a><button class="quiet" data-video-complete="${e(v.id)}" aria-pressed="${done}">${done?'✓ Revisado':'Marcar revisão'}</button></div></div></article>`}
function videosPage(id){const all=D.videos.videos,v=all.find(x=>x.id===id)||all.find(x=>x.id==='til92X5hYAY')||all[0];const items=filtered(all).filter(x=>(!videoKind||x.kind===videoKind)&&(!videoChannel||x.channel===videoChannel));const total=all.reduce((s,x)=>s+x.seconds,0);return `${title('ASSISTA · PAUSE · DESENHE · DEFENDA','Videoteca de System Design','50 vídeos públicos, com entrevistas simuladas e walkthroughs de problemas de Big Tech. Guias de estudo em português para transformar conteúdo em decisões.',`<a class="button" href="#mocks">Praticar por 60 minutos ↗</a>`)}<section class="video-intro panel"><div><span class="eyebrow">CURADORIA PARA ESTUDO ATIVO</span><h2>Transforme cada vídeo em uma decisão que você consegue defender.</h2><p>Antes de assistir, escreva requisitos e invariantes. Pause antes da solução, defenda uma escolha e provoque uma falha. Depois compare seu raciocínio com a abordagem apresentada.</p></div><div class="video-totals"><strong>${all.length}<small>vídeos únicos</small></strong><strong>${videoDuration(total)}<small>de conteúdo no YouTube</small></strong><strong id="video-progress">${all.filter(x=>progress.checks.includes(`video:${x.id}`)).length}<small>revisados por você</small></strong></div></section><div class="video-workspace"><section class="panel video-feature"><div class="actions">${chip(v.kind)}${chip(v.level,'green')}</div><h2>${e(v.title)}</h2><p class="video-author">${e(v.channel)} · ${e(v.duration)} · áudio e legendas conforme disponibilidade no YouTube</p><div class="video-player" id="video-player"><img src="${e(v.thumbnail)}" alt="Prévia de ${e(v.title)}" width="480" height="360"><button class="video-load" data-video-load="${e(v.id)}"><span aria-hidden="true">▶</span> Carregar player do YouTube</button></div><div class="video-external"><a href="${e(v.url)}" target="_blank" rel="noopener" class="button small">Abrir no YouTube ↗</a><a href="${e(v.channelUrl)}" target="_blank" rel="noopener">Canal do autor ↗</a></div><p class="foundation-caption">O player externo carrega após seu clique. Se a incorporação não estiver disponível, use o link do YouTube. Vídeos, anúncios, legendas e disponibilidade são controlados pelos autores e pela plataforma.</p></section><aside class="panel video-study"><span class="eyebrow">ROTEIRO AUTORAL DE ESTUDO</span><h2>O que você precisa conseguir explicar</h2><p>${e(v.guide)}</p><ol>${v.focus.map(x=>`<li>${e(x)}</li>`).join('')}</ol><div class="note"><strong>Leve para uma fintech</strong><p>${e(v.challenge)}</p></div><div class="actions">${v.relatedArchitectures.map(id=>{const a=D.architectures.find(x=>x.id===id);return a?`<a class="chip" href="#atlas/${e(id)}">${e(a.title)} ↗</a>`:''}).join('')}</div><label class="video-notes">Sua hipótese antes de assistir<textarea data-note="video:${e(v.id)}" rows="4" placeholder="Qual é a invariante? Onde está o gargalo? O que a pessoa vê se falhar?">${e(progress.notes[`video:${v.id}`]||'')}</textarea></label><button class="button" data-video-complete="${e(v.id)}" aria-pressed="${progress.checks.includes(`video:${v.id}`)}">${progress.checks.includes(`video:${v.id}`)?'✓ Revisado':'Marcar revisão'}</button></aside></div><section class="panel video-method"><details><summary>Como esta curadoria foi verificada e como usar os mocks</summary><p>Títulos, canais, URLs e duração foram conferidos em playlists públicas e metadados do YouTube; descrições disponíveis também foram consultadas. Pesquisa em ${e(D.videos.verifiedAtLabel)}. Os roteiros em português são exercícios editoriais baseados no tema e na descrição, não transcrições, resumos de uma visualização integral nem endosso de todas as escolhas dos vídeos.</p><p>“Entrevista simulada” representa uma sessão apresentada pelo canal como mock/interview; “Walkthrough” representa uma explicação guiada. Empresas e cargos citados nos títulos são apresentados pelos próprios autores. Estes materiais não são gravações confidenciais de processos seletivos, nem arquiteturas internas oficiais das empresas ou previsões do teste do Nubank.</p><p>Use o tempo do seu simulado, não a duração do vídeo: 0–10 min requisitos e invariantes; 10–20 min API e dados; 20–35 min caminho principal; 35–50 min gargalos e falhas; 50–60 min trade-offs, recuperação e síntese. Refazer um mesmo problema com outro autor é um exercício de comparação.</p></details></section><div class="section-heading"><h2>Os 50 vídeos, em uma página</h2><a href="#foundations">Reforçar os fundamentos →</a></div><div class="filters video-filters"><input type="search" id="filter-q" aria-label="Pesquisar vídeos" placeholder="Buscar tema, empresa ou autor…" value="${e(filter.q)}"><select id="filter-category" aria-label="Filtrar tema">${options(all.map(x=>x.topic),filter.category,'Todos os temas')}</select><select id="video-kind" aria-label="Filtrar formato">${options(all.map(x=>x.kind),videoKind,'Todos os formatos')}</select><select id="video-channel" aria-label="Filtrar canal">${options(all.map(x=>x.channel),videoChannel,'Todos os canais')}</select></div><div class="result-line" id="video-count"><span>${items.length} de ${all.length} vídeos</span><span>Links originais · sem download dos vídeos</span></div><div class="video-grid">${items.map(v=>videoCard(v,all.indexOf(v))).join('')||'<div class="empty">Nenhum vídeo com esses filtros. Experimente outro tema.</div>'}</div>`}
function bindVideos(){for(const [id,set] of [['video-kind',v=>videoKind=v],['video-channel',v=>videoChannel=v]])if($('#'+id))$('#'+id).onchange=()=>{set($('#'+id).value);updateVideoCatalogue()};$$('[data-video-complete]').forEach(b=>b.onclick=()=>{const id=b.dataset.videoComplete;const persisted=toggle(progress.checks,`video:${id}`);$$(`[data-video-complete="${id}"]`).forEach(button=>{const done=progress.checks.includes(`video:${id}`);button.textContent=done?'✓ Revisado':'Marcar revisão';button.setAttribute('aria-pressed',String(done))});if($('#video-progress'))$('#video-progress').innerHTML=`${D.videos.videos.filter(x=>progress.checks.includes(`video:${x.id}`)).length}<small>revisados por você</small>`;if(persisted)toast('Revisão salva neste dispositivo')});$$('[data-video-load]').forEach(b=>b.onclick=()=>{const v=D.videos.videos.find(x=>x.id===b.dataset.videoLoad);if(!v)return;$('#video-player').innerHTML=`<iframe src="https://www.youtube-nocookie.com/embed/${e(v.id)}?rel=0" title="${e(v.title)}" loading="eager" referrerpolicy="strict-origin-when-cross-origin" allow="accelerometer; clipboard-write; encrypted-media; gyroscope; picture-in-picture; web-share" allowfullscreen></iframe>`})}

function updateVideoCatalogue(){const all=D.videos.videos,items=filtered(all).filter(x=>(!videoKind||x.kind===videoKind)&&(!videoChannel||x.channel===videoChannel));$('.video-grid').innerHTML=items.map(v=>videoCard(v,all.indexOf(v))).join('')||'<div class="empty">Nenhum vídeo com esses filtros. Experimente outro tema.</div>';$('#video-count').innerHTML=`<span>${items.length} de ${all.length} vídeos</span><span>Links originais · sem download dos vídeos</span>`;bindVideos()}

let courseQuery='',courseResourceQuery='',courseResourceType='';
const coursePhase=n=>n<=6?'Fundamentos':n<=14?'Comunicação & serviços':n<=21?'Escala & dados':'Operação & resiliência';
function courseResource(r){return `<a class="course-resource" href="${e(r.url)}" target="_blank" rel="noopener"><span><strong>${e(r.title)}${r.statusNote?' · '+e(r.statusNote):''}</strong><small>${e(r.external?'Material externo · '+r.type:r.path||r.originPath||r.type)}</small></span><span class="chip neutral">${e(r.type)} ↗</span></a>`}
function courseLessonCard(l){const slides=l.resources.find(x=>x.type==='Slides'),done=progress.checks.includes(`course:${l.id}`);return `<article class="course-lesson ${currentId===l.id?'selected':''}"><div class="course-lesson-number">${String(l.number).padStart(2,'0')}<small>${e(coursePhase(l.number))}</small></div><div class="course-lesson-main"><h3><a href="#course/${e(l.id)}">${e(l.title)}</a></h3><p>${e(l.summary.replace('Guia autoral para entrevista: ',''))}</p><div class="course-topics">${l.topics.map(x=>chip(x,'neutral')).join('')}</div><div class="actions"><a class="button small" href="#course/${e(l.id)}">Abrir aula →</a><a href="${e(slides.url)}" target="_blank" rel="noopener" class="button small">Slides originais ↗</a><button class="quiet" data-course-complete="${e(l.id)}" aria-pressed="${done}">${done?'✓ Estudada':'Marcar estudo'}</button></div></div></article>`}
function courseFileInventory(){const all=[...D.course.lessons.flatMap(l=>l.resources.filter(r=>!r.external)),...D.course.otherResources];const items=all.filter(r=>(!courseResourceQuery||matches({title:r.title,path:r.path,group:r.group},courseResourceQuery))&&(!courseResourceType||r.type===courseResourceType));const groups=new Map();for(const r of items){if(!groups.has(r.group))groups.set(r.group,[]);groups.get(r.group).push(r)}return `<div class="result-line"><span>${items.length} de ${all.length} arquivos</span><span>Versão ${e(D.course.commit.slice(0,7))}</span></div>${[...groups].map(([group,files])=>`<details class="course-file-group" ${courseResourceQuery||courseResourceType?'open':''}><summary>${e(group)} <span>${files.length} arquivos</span></summary>${files.map(courseResource).join('')}</details>`).join('')||'<div class="empty">Nenhum arquivo com esse filtro.</div>'}`}
function coursePage(id){const c=D.course,l=c.lessons.find(x=>x.id===id)||c.lessons[0],slides=l.resources.find(r=>r.type==='Slides'),files=l.resources.filter(r=>r.type!=='Slides');return `${title('LINUXTIPS · CURSO + PRÁTICA','Descomplicando o System Design','Todas as aulas e apresentações listadas no repositório, com exemplos, cases e conexões para aprofundar cada decisão no portal.',`<a class="button" href="${e(c.repositoryUrl)}" target="_blank" rel="noopener">Repositório original indicado ↗</a>`)}<section class="course-hero panel"><div><span class="eyebrow">DO MATERIAL À ARGUMENTAÇÃO</span><h2>Estude a aula.<br>Defenda a arquitetura.</h2><p>Siga a sequência do curso ou vá direto ao tema que precisa dominar. Os materiais de LINUXtips e msfidelis permanecem em suas fontes originais; cada aula ganha um roteiro de aplicação à entrevista.</p><div class="course-stats">${[[29,'aulas com slides'],[26,'artigos'],[26,'cases'],[341,'arquivos catalogados']].map(([n,t])=>`<div><strong>${n}</strong><span>${t}</span></div>`).join('')}</div></div><div class="course-map" aria-label="Trilha de aprendizado"><div><span>01</span><strong>Fundamentos</strong><small>Rede · dados · consistência</small></div><i>↓</i><div><span>02</span><strong>Fronteiras</strong><small>Serviços · protocolos · eventos</small></div><i>↓</i><div><span>03</span><strong>Escala</strong><small>Partições · réplicas · workflows</small></div><i>↓</i><div><span>04</span><strong>Operação</strong><small>Falhas · capacidade · observabilidade</small></div></div></section><div class="course-workspace"><section class="panel course-feature"><div class="actions">${chip('AULA '+String(l.number).padStart(2,'0'))}${chip(coursePhase(l.number),'green')}</div><h2>${e(l.title)}</h2><div class="course-slide" id="course-slide"><div class="course-slide-cover"><span class="eyebrow">APRESENTAÇÃO ORIGINAL</span><strong>${e(l.title)}</strong><span>LINUXtips · Descomplicando o System Design</span><button class="button primary" data-course-slides="${e(l.id)}">Carregar apresentação ↗</button></div></div><div class="actions"><a class="button small" href="${e(slides.url)}" target="_blank" rel="noopener">Abrir no Google Slides ↗</a>${l.links.filter(r=>r.type==='Artigo').map(r=>`<a class="button small" href="${e(r.url)}" target="_blank" rel="noopener">${r.statusNote?'Artigo original · 404':'Ler artigo da aula'} ↗</a>`).join('')}</div><p class="foundation-caption">A apresentação externa carrega após seu clique. Se o autor restringir a incorporação ou o acesso, abra o link original. O repositório contém materiais de aula, sem links de gravações em vídeo.</p>${l.links.some(r=>r.statusNote)?'<div class="note">O artigo original desta aula retornou 404 na verificação. Use os slides e os aprofundamentos do atlas.</div>':''}${files.length||l.links.filter(r=>r.type!=='Artigo').length?`<details class="course-file-group"><summary>Exemplos e complementos desta aula <span>${files.length+l.links.filter(r=>r.type!=='Artigo').length}</span></summary>${[...files,...l.links.filter(r=>r.type!=='Artigo')].map(courseResource).join('')}</details>`:''}</section><aside class="panel course-study"><span class="eyebrow">GUIA AUTORAL · APLIQUE NA ENTREVISTA</span><h2>O que levar para o desenho</h2><p>${e(l.summary.replace('Guia autoral para entrevista: ',''))}</p><ol><li>Declare o requisito que justifica a escolha e o custo de uma alternativa.</li><li>Siga uma operação até o commit: onde ficam estado, concorrência e durabilidade?</li><li>Interrompa uma dependência. Explique detecção, recuperação e o que o cliente vê.</li></ol><h3>Aprofunde no atlas</h3><div class="course-related">${l.relatedArchitectures.map(id=>{const a=D.architectures.find(x=>x.id===id);return a?`<a href="#atlas/${e(id)}?tab=operations"><span>${e(a.title)}</span><small>Gargalos · falhas · SLA ↗</small></a>`:''}).join('')}</div><label class="video-notes">Sua decisão e o trade-off<textarea data-note="course:${e(l.id)}" rows="4" placeholder="Escolho… porque… Abro mão de… Se falhar, o usuário…">${e(progress.notes[`course:${l.id}`]||'')}</textarea></label><button class="button" data-course-complete="${e(l.id)}" aria-pressed="${progress.checks.includes(`course:${l.id}`)}">${progress.checks.includes(`course:${l.id}`)?'✓ Estudada':'Marcar estudo'}</button></aside></div><section class="panel course-catalogue"><div class="panel-heading"><div><span class="eyebrow">A SEQUÊNCIA COMPLETA</span><h2>Todas as 29 aulas</h2></div><span class="chip green" id="course-progress">${c.lessons.filter(x=>progress.checks.includes(`course:${x.id}`)).length} / 29 estudadas</span></div><label class="course-search">Encontre uma aula<input id="course-query" type="search" placeholder="Cache, Saga, replicação, observabilidade…" value="${e(courseQuery)}"></label><div id="course-lesson-count" class="result-line" aria-live="polite"></div><div id="course-lessons">${c.lessons.filter(x=>!courseQuery||matches({title:x.title,topics:x.topics,summary:x.summary},courseQuery)).map(courseLessonCard).join('')}</div></section><section class="panel"><span class="eyebrow">ACERVO COMPLETO DO REPOSITÓRIO</span><h2>Cases, diagramas e código, sem perder nenhum arquivo.</h2><p>26 cases, 16 diagramas de resolução e exemplos de implementação. Inclui três exercícios presentes na pasta de cases que não estavam ligados no índice principal. Os arquivos estão fixados no commit catalogado para manter a referência estável.</p><div class="filters course-file-filters"><input id="course-file-query" type="search" aria-label="Buscar arquivo do curso" placeholder="Buscar case, arquivo ou diretório…" value="${e(courseResourceQuery)}"><select id="course-file-type" aria-label="Filtrar tipo de arquivo">${options(['Aula','Código','Recurso','Diagrama'],courseResourceType,'Todos os tipos de arquivo')}</select></div><div id="course-inventory">${courseFileInventory()}</div></section><section class="panel course-provenance"><details><summary>Fontes, cobertura e links do material original</summary><p>Catálogo conferido em ${e(c.checkedAt)}. ${e(c.coverage.numberingNote)} ${e(c.coverage.summaryMethod)}</p><p>${e(c.coverage.scope)} ${e(c.coverage.linkVerification)}</p><p>Há 29 apresentações externas; o repositório não contém arquivos PDF/PPT nem links de vídeos das aulas. Para sessões gravadas de System Design, consulte a <a href="#videos">videoteca do portal</a>.</p><p>${e(c.coverage.licenseNote)} Autoria e marcas pertencem aos respectivos responsáveis. Consulte o <a href="${e(c.upstreamUrl)}" target="_blank" rel="noopener">repositório de origem de msfidelis</a>.</p><h3>Problemas encontrados na origem</h3>${list(c.coverage.warnings.map(w=>`${w.path}${w.target?' → '+w.target:''}: ${w.reason}`))}<details class="course-file-group"><summary>Todos os ${c.allLinks.length} links externos encontrados</summary>${c.allLinks.map(courseResource).join('')}</details>${refs(c.sources.map(s=>s.id))}</details></section>`}
function bindCourse(){$$('[data-course-complete]').forEach(b=>b.onclick=()=>{const id=b.dataset.courseComplete;const persisted=toggle(progress.checks,`course:${id}`);$$(`[data-course-complete="${id}"]`).forEach(button=>{const done=progress.checks.includes(`course:${id}`);button.textContent=done?'✓ Estudada':'Marcar estudo';button.setAttribute('aria-pressed',String(done))});$('#course-progress').textContent=`${D.course.lessons.filter(x=>progress.checks.includes(`course:${x.id}`)).length} / 29 estudadas`;if(persisted)toast('Estudo salvo neste dispositivo')});$$('[data-course-slides]').forEach(b=>b.onclick=()=>{const lesson=D.course.lessons.find(x=>x.id===b.dataset.courseSlides),url=lesson?.resources.find(r=>r.type==='Slides')?.url;const slideId=url?.match(/^https:\/\/docs\.google\.com\/presentation\/d\/([\w-]+)\//)?.[1];if(!slideId)return;$('#course-slide').innerHTML=`<iframe src="https://docs.google.com/presentation/d/${e(slideId)}/embed?start=false&loop=false&delayms=3000" title="Slides: ${e(lesson.title)}" referrerpolicy="strict-origin-when-cross-origin" allowfullscreen></iframe>`});if($('#course-query'))$('#course-query').oninput=()=>{courseQuery=$('#course-query').value;const items=D.course.lessons.filter(x=>!courseQuery||matches({title:x.title,topics:x.topics,summary:x.summary},courseQuery));$('#course-lessons').innerHTML=items.map(courseLessonCard).join('')||'<div class="empty">Nenhuma aula com esse termo.</div>';$('#course-lesson-count').textContent=`${items.length} de 29 aulas`;bindCourse()};for(const id of ['course-file-query','course-file-type'])if($('#'+id))$('#'+id)[id.endsWith('query')?'oninput':'onchange']=()=>{courseResourceQuery=$('#course-file-query').value;courseResourceType=$('#course-file-type').value;$('#course-inventory').innerHTML=courseFileInventory()}}


let guidedStep=0,guidedRehearse=false,guidedRevealed=false,guidedFinal=false;
const guidedCase=()=>D.guided.cases.find(c=>c.id===currentId)||D.guided.cases[0];
const guidedRange=s=>`${String(s.minute).padStart(2,'0')}–${String(s.minute+s.duration).padStart(2,'0')} min`;
const guidedOpen=()=>!guidedRehearse||guidedRevealed;
function guidedCard(c,i){const done=c.steps.filter((_,j)=>progress.checks.includes(`guided:${c.id}:step:${j}`)).length;return `<a class="guided-case ${guidedCase()?.id===c.id?'active':''}" href="#guided/${e(c.id)}"><span class="guided-case-number">0${i+1}<small>${e(c.evidence.kind)}</small></span><strong>${e(c.title)}</strong><span>${e(c.subtitle)}</span><small>${done} / 10 etapas praticadas · 60 min ↗</small></a>`}
function guidedNodeLines(label){const words=label.split(' '),lines=[''];for(const word of words){const i=lines.length-1;if(lines[i]&&lines[i].length+word.length+1>20)lines.push(word);else lines[i]+=(lines[i]?' ':'')+word}return lines}
function guidedBoard(c,s){const visibleStep=guidedOpen()?(guidedFinal?9:guidedStep):guidedStep-1;const nodes=c.nodes.filter(n=>n.firstStep<=visibleStep),ids=new Set(nodes.map(n=>n.id));const edges=c.edges.filter(a=>a.firstStep<=visibleStep&&ids.has(a.from)&&ids.has(a.to));return `<div class="guided-board-head"><span>${guidedFinal?'DESENHO COMPLETO':guidedOpen()?'DESENHANDO COM A FALA':'SEU QUADRO ANTES DA RESPOSTA'}</span><button class="quiet" id="guided-final" ${!guidedOpen()?'disabled':''}>${guidedFinal?'Voltar à etapa':'Ver desenho final'}</button></div><div class="guided-board ${guidedOpen()?'':'concealed'}"><svg viewBox="0 0 980 460" role="group" aria-label="Arquitetura progressiva: ${e(c.title)}"><defs><marker id="guided-arrow" markerWidth="7" markerHeight="7" refX="6" refY="3.5" orient="auto"><path d="M0 0 7 3.5 0 7" fill="#a18ab8"/></marker><pattern id="guided-grid" width="20" height="20" patternUnits="userSpaceOnUse"><circle cx="1" cy="1" r="1" fill="#b797d229"/></pattern></defs><rect width="980" height="460" fill="url(#guided-grid)"/>${edges.map((a,i)=>{const f=nodes.find(n=>n.id===a.from),t=nodes.find(n=>n.id===a.to);const dx=t.x-f.x,dy=t.y-f.y,horizontal=dy===0,parallel=edges.filter(b=>(b.from===a.from&&b.to===a.to)||(b.to===a.from&&b.from===a.to)).length>1;let path,mx,my;
if(horizontal&&Math.abs(dx)<300&&!parallel){const a=f.x+Math.sign(dx)*83,b=t.x-Math.sign(dx)*88;path=`M${a} ${f.y} H${b}`;mx=(a+b)/2;my=f.y}
else if(dx===0&&Math.abs(dy)<180){const a=f.y+Math.sign(dy)*32,b=t.y-Math.sign(dy)*37;path=`M${f.x} ${a} V${b}`;mx=f.x;my=(a+b)/2}
else{const direction=Math.sign(dy)||(f.y>300?-1:1),sy=f.y+direction*32,ty=dy?t.y-direction*37:t.y+direction*37,lane=f.y+direction*(52+(i%3)*23);if(Math.abs(dy)>180){const side=dx? -Math.sign(dx):(t.x>750?-1:1),corridor=t.x+side*(112+(i%2)*10),endLane=t.y-direction*(59+(i%3)*9);path=`M${f.x} ${sy} V${lane} H${corridor} V${endLane} H${t.x} V${ty}`;mx=corridor;my=(lane+endLane)/2}
else{path=`M${f.x} ${sy} V${lane} H${t.x} V${ty}`;mx=f.x+(t.x-f.x)*.48;my=lane}}
const edgeIndex=c.edges.indexOf(a);return `<g class="guided-edge ${a.firstStep===visibleStep&&!guidedFinal?'fresh':''}" data-guided-edge="${edgeIndex}" role="button" tabindex="0" aria-label="Fluxo ${edgeIndex+1}: ${e(f.label)} para ${e(t.label)} — ${e(a.label)}"><path d="${path}" marker-end="url(#guided-arrow)"/><circle class="guided-particle" r="2.5"><animateMotion dur="${3+i*.23}s" repeatCount="indefinite" path="${path}"/></circle><g class="guided-edge-badge"><circle cx="${mx}" cy="${my}" r="9"/><text x="${mx}" y="${my+3.5}" text-anchor="middle">${edgeIndex+1}</text></g></g>`}).join('')}${nodes.map(n=>{const logo=D.technologies.find(t=>t.id===n.tech)?.logo,lines=guidedNodeLines(n.label);return `<g class="guided-node ${n.firstStep===visibleStep&&!guidedFinal?'fresh':''} ${s.focusNodes.includes(n.id)?'focus-node':''} ${e(n.kind)}" tabindex="0" role="button" data-guided-node="${e(n.id)}" aria-label="Inspecionar ${e(n.label)}"><rect x="${n.x-83}" y="${n.y-32}" width="166" height="64" rx="${n.kind==='actor'?30:12}"/>${logo?`<image href="${e(logo)}" x="${n.x-72}" y="${n.y-9}" width="18" height="18"/>`:''}${lines.map((line,j)=>`<text x="${n.x+(logo?10:0)}" y="${n.y+4-(lines.length-1)*7+j*14}" text-anchor="middle">${e(line)}</text>`).join('')}</g>`}).join('')}${nodes.length?'':`<text x="490" y="210" text-anchor="middle" class="guided-empty-board">Comece pelo cliente e pela fronteira do problema.</text><text x="490" y="235" text-anchor="middle" class="guided-empty-board">Revele a resposta para acompanhar o primeiro desenho.</text>`}</svg></div><p class="guided-board-hint">Selecione uma peça ou um número para explicar a responsabilidade e o fluxo. No celular, deslize o quadro na horizontal.</p>${edges.length?`<details class="guided-flow-list"><summary>Explicar os ${edges.length} fluxos desenhados</summary><ol>${edges.map(a=>{const n=c.edges.indexOf(a);return `<li><button data-guided-flow="${n}"><b>${n+1}</b><span><strong>${e(c.nodes.find(x=>x.id===a.from).label)} → ${e(c.nodes.find(x=>x.id===a.to).label)}</strong><small>${e(a.label)}</small></span></button></li>`}).join('')}</ol></details>`:''}<div class="guided-board-legend"><span><i></i>Já desenhado</span><span><i class="new"></i>Acrescentado nesta etapa</span><button class="quiet" id="guided-motion">Pausar fluxo</button></div><div id="guided-node-detail" class="guided-node-detail" aria-live="polite">Clique em uma peça para explicar estado, garantia e responsabilidade.</div>${guidedOpen()?`<div class="guided-draw"><span class="eyebrow">O QUE VOCÊ DESENHA AGORA</span><ol>${s.draw.map(x=>`<li>${e(x)}</li>`).join('')}</ol></div>`:'<div class="guided-draw"><p>Explique sua decisão em voz alta e desenhe no seu quadro antes de revelar a resposta. A visualização conserva somente as peças das etapas anteriores.</p></div>'}`}
function guidedDialogue(s){return `<div class="guided-dialogue interviewer"><span>ENTREVISTADOR · FALA SIMULADA</span><p>${e(s.interviewer)}</p></div>${guidedOpen()?`<div class="guided-dialogue candidate"><span>VOCÊ · UMA RESPOSTA DEFENSÁVEL</span>${s.candidate.map(p=>`<p>${e(p)}</p>`).join('')}</div><div class="guided-checkpoint"><strong>Pare e colabore</strong><p>${e(s.checkpoint)}</p></div>`:`<div class="guided-hidden-answer"><strong>Sua vez de conduzir.</strong><p>Responda antes de consultar. Registre a invariante, a alternativa e a falha que sua proposta precisa suportar.</p><button class="button primary" id="guided-reveal">Revelar fala e desenho →</button></div>`}`}
function guidedMechanics(s){return `<section class="panel guided-mechanics"><div class="panel-heading"><div><span class="eyebrow">POR TRÁS DA RESPOSTA</span><h2>Transforme a fala em mecanismo.</h2></div>${chip('APROFUNDAMENTO TÉCNICO')}</div><div class="two-col">${s.mechanics.map(m=>`<article><h3>${e(m.title)}</h3><p>${e(m.body)}</p></article>`).join('')}</div><h3>${e(s.artifact.title)}</h3><span class="foundation-caption">${e(s.artifact.language)} · contrato ou pseudocódigo didático; precisa de implementação e testes no sistema real</span><pre tabindex="0"><code>${e(s.artifact.code)}</code></pre><div class="guided-decision"><h3>A decisão e a alternativa</h3><dl><dt>Escolha</dt><dd>${e(s.decision.choice)}</dd><dt>Alternativa</dt><dd>${e(s.decision.alternative)}</dd><dt>Por que agora</dt><dd>${e(s.decision.why)}</dd><dt>Quando eu mudaria</dt><dd>${e(s.decision.whenToChange)}</dd></dl></div><div class="guided-principal"><span class="eyebrow">AMPLIE A RESPONSABILIDADE · PRINCIPAL</span><p>${e(s.principal)}</p></div></section><section class="panel guided-challenge"><span class="eyebrow">O ENTREVISTADOR INTERROMPE</span><h2>${e(s.challenge.question)}</h2><details><summary>Ver como responder e adaptar o desenho</summary><p>${e(s.challenge.answer)}</p><div class="note"><strong>O que muda no quadro</strong><p>${e(s.challenge.pivot)}</p></div></details></section>`}
function guidedTranscript(c){return `<details class="panel guided-transcript"><summary>Ler o roteiro completo de 60 minutos</summary><p>Falas autorais de treino. Use pausas e checkpoints: uma entrevista real é uma conversa, e o entrevistador pode escolher outro aprofundamento.</p>${c.steps.map((s,i)=>`<details><summary>${guidedRange(s)} · ${e(s.title)}</summary><div class="guided-dialogue interviewer"><span>ENTREVISTADOR</span><p>${e(s.interviewer)}</p></div><div class="guided-dialogue candidate"><span>VOCÊ</span>${s.candidate.map(p=>`<p>${e(p)}</p>`).join('')}</div><h4>Enquanto fala, desenhe</h4>${list(s.draw)}<p><strong>Checkpoint:</strong> ${e(s.checkpoint)}</p><button class="button small" data-guided-step="${i}">Abrir esta etapa no quadro ↗</button></details>`).join('')}</details>`}
function guidedPage(id){const c=guidedCase();if(!c)return notFound();if(timer.id!==`guided:${c.id}`)timer={id:`guided:${c.id}`,elapsed:0,running:false,start:0};const s=c.steps[guidedStep],done=progress.checks.includes(`guided:${c.id}:step:${guidedStep}`);return `${title('CINCO CASOS · FALA + QUADRO + DECISÃO','Conduza o desenho em voz alta.','Entrevistas guiadas de 60 minutos: o que perguntar, como responder, o que desenhar e como reagir quando a primeira solução deixa de funcionar.')}<section class="guided-intro panel"><div><span class="eyebrow">DO REQUISITO AO PLANO DE EVOLUÇÃO</span><h2>Explique cada caixa.<br>Defenda cada decisão.</h2><p>Em cada etapa você lê a pergunta, acompanha uma resposta em primeira pessoa e vê a arquitetura crescer. Depois entra no mecanismo, enfrenta uma falha e decide o que faria mudar de ideia.</p><div class="actions">${chip('5 CASOS')}${chip('50 ETAPAS','neutral')}${chip('300 MIN DE PRÁTICA','green')}</div></div><ol class="guided-method"><li><b>01</b><span>Leia ou ensaie<strong>Responda antes de revelar.</strong></span></li><li><b>02</b><span>Desenhe enquanto explica<strong>Estado, contratos e fronteiras.</strong></span></li><li><b>03</b><span>Defenda e adapte<strong>Falhas, custo e evolução.</strong></span></li></ol></section><details class="panel guided-framework"><summary>O padrão de raciocínio para levar a qualquer enunciado</summary><p>Use esta sequência como orientação e renegocie o foco quando surgirem novas restrições. Os casos abaixo mostram a sequência em ação.</p><ol><li><strong>Reformule a jornada.</strong> “Quero confirmar quem inicia, o que considera sucesso e qual erro seria mais caro.”</li><li><strong>Declare uma invariante.</strong> “Mesmo que uma resposta se perca, este efeito não pode ocorrer duas vezes. Vou localizar a fronteira que garante isso.”</li><li><strong>Faça uma conta que muda a decisão.</strong> “Com este pico, tempo de serviço e payload, esta peça exige esta capacidade. Vou validar a hipótese antes de distribuir mais estado.”</li><li><strong>Feche o caminho mínimo.</strong> “Aqui aceito a intenção; aqui faço o commit; aqui respondo. Uma confirmação externa ainda está pendente.”</li><li><strong>Interrompa o fluxo.</strong> “Se cair exatamente depois deste commit, quem retoma, com qual identidade e como descobre o resultado?”</li><li><strong>Mostre o preço da escolha.</strong> “Esta alternativa simplifica a operação, mas limita a escala neste ponto. Eu mudaria quando esta medição cruzasse este limite.”</li><li><strong>Amplie para a operação.</strong> “Quem recebe o alerta, qual jornada se degrada, como restauramos e que evidência prova o RTO/RPO?”</li><li><strong>Conclua com evolução verificável.</strong> “Entrego primeiro este fluxo, valido estas hipóteses e migro por estas etapas. O risco residual é este. Qual ponto você quer aprofundar?”</li></ol><p>Profundidade Principal aparece também em reduzir complexidade, negociar contratos entre times e propor uma migração segura. Se o entrevistador encurtar a sessão, priorize a invariante, o fluxo mínimo, uma falha crítica e os trade-offs; combine o restante.</p></details><nav class="guided-cases" aria-label="Escolher caso guiado">${D.guided.cases.map(guidedCard).join('')}</nav><section class="panel guided-brief"><div class="actions">${chip(c.evidence.kind)}${chip('ROTEIRO AUTORAL','neutral')}</div><h2>${e(c.title)}</h2><p>${e(c.brief)}</p><details><summary>O que é evidência e o que é hipótese deste exercício</summary><p>${e(c.evidence.summary)}</p><p>${e(c.evidence.limits)}</p>${refs(c.evidence.sourceIds)}<p>Não há garantia de aprovação nem rubrica oficial de Staff/Principal nesta página. As falas, escalas, metas e propostas abaixo são material de treino; adapte-as às respostas e prioridades de quem conduz a entrevista. Combine a agenda: se houver menos tempo de desenho, preserve o fluxo mínimo e peça a prioridade do aprofundamento.</p></details><details><summary>Premissas, invariantes e critério de sucesso</summary><div class="table-wrap"><table><thead><tr><th>Premissa hipotética</th><th>Valor para o exercício</th><th>Por que importa</th></tr></thead><tbody>${c.assumptions.map(a=>`<tr><td>${e(a.label)}</td><td>${e(a.value)}</td><td>${e(a.why)}</td></tr>`).join('')}</tbody></table></div><h3>O que não pode acontecer</h3>${list(c.invariants)}<p><strong>Critério proposto:</strong> ${e(c.success)}</p></details></section>${timerHtml().replace('timer-shell','timer-shell guided-timer')}<div class="guided-mode-bar"><label><input type="checkbox" id="guided-rehearse" ${guidedRehearse?'checked':''}> Modo ensaio: responder antes de revelar</label><button class="button small" id="guided-download">Baixar roteiro em texto ↓</button></div><nav class="guided-stages" aria-label="Etapas do roteiro">${c.steps.map((x,i)=>`<button data-guided-step="${i}" class="${i===guidedStep?'active':''}" aria-current="${i===guidedStep?'step':'false'}"><span>${String(i+1).padStart(2,'0')}</span><strong>${e(x.title)}</strong><small>${guidedRange(x)}</small></button>`).join('')}</nav><div class="guided-step-heading" id="guided-step-heading"><div><span class="eyebrow">ETAPA ${String(guidedStep+1).padStart(2,'0')} / 10 · ${guidedRange(s)}</span><h2 id="guided-step-title" tabindex="-1">${e(s.title)}</h2><p>${e(s.goal)}</p></div><div class="actions"><button class="button small" id="guided-prev" ${guidedStep===0?'disabled':''}>← Anterior</button><button class="button small primary" id="guided-next" ${guidedStep===9?'disabled':''}>Próxima →</button></div></div><div class="guided-workspace"><section class="panel guided-whiteboard">${guidedBoard(c,s)}</section><section class="guided-conversation">${guidedDialogue(s)}</section></div>${guidedOpen()?guidedMechanics(s):''}<section class="panel guided-notes"><div><span class="eyebrow">REGISTRE SUA VERSÃO</span><h2>O que você diria sem consultar?</h2><p>Praticar esta etapa não é uma avaliação de aprovação. Refaça com premissas diferentes e observe se a decisão continua válida.</p><button class="button" id="guided-complete" aria-pressed="${done}">${done?'✓ Etapa praticada':'Marcar etapa praticada'}</button></div><label>Sua resposta, lacuna ou decisão<textarea data-note="guided:${e(c.id)}:step:${guidedStep}" rows="6" placeholder="Minha invariante é… A escolha custa… Se cair aqui… Eu mudaria de ideia se…">${e(progress.notes[`guided:${c.id}:step:${guidedStep}`]||'')}</textarea></label></section><details class="panel guided-drills"><summary>Três incidentes para testar o desenho final</summary><p>Use estas mudanças depois de estabelecer um fluxo coerente. Peça para outra pessoa escolher uma sem avisar.</p>${c.failureDrills.map(d=>`<article><h3>${e(d.failure)}</h3><dl>${[['detection','Como detecto'],['containment','Como contenho'],['recovery','Como recupero'],['userExperience','O que o cliente vê'],['sli','O que eu meço']].map(([k,t])=>`<dt>${t}</dt><dd>${e(d[k])}</dd>`).join('')}</dl></article>`).join('')}</details><details class="panel guided-deployments"><summary>Implementação em AWS, Azure ou on-premises</summary><p>Opções propostas para o exercício, não uma confirmação dos produtos usados internamente pelo Nubank. Configure e teste as garantias de cada alternativa.</p>${Object.entries(c.deployment).map(([k,v])=>`<h3>${k==='aws'?'AWS':k==='azure'?'Azure':'On-premises'}</h3><p>${e(v)}</p>`).join('')}</details><details class="panel guided-rubric"><summary>Autoavaliação: evidências de profundidade Staff e Principal</summary><p>Rubrica pedagógica do portal. O título de um cargo não é determinado por uma resposta isolada, e nenhuma pontuação abaixo prevê contratação.</p><div class="table-wrap"><table><thead><tr><th>Dimensão</th><th>Sinal Staff</th><th>Ampliação Principal</th><th>Alerta</th></tr></thead><tbody>${c.rubric.map(r=>`<tr><td>${e(r.dimension)}</td><td>${e(r.staff)}</td><td>${e(r.principal)}</td><td>${e(r.redFlag)}</td></tr>`).join('')}</tbody></table></div><h3>Uma forma de encerrar</h3><p>${e(c.closing)}</p></details>${guidedTranscript(c)}<section class="panel guided-links"><h3>Continue a partir desta decisão</h3><div class="actions">${c.relatedArchitectures.map(id=>{const a=D.architectures.find(x=>x.id===id);return a?`<a class="chip" href="#atlas/${e(id)}?tab=operations">${e(a.title)} ↗</a>`:''}).join('')}</div>${refs(c.sourceIds)}</section>`}
function guidedMove(index){guidedStep=Math.max(0,Math.min(9,index));guidedRevealed=false;guidedFinal=false;history.replaceState(null,'',`#guided/${guidedCase().id}?step=${guidedStep+1}${guidedRehearse?'&mode=rehearse':''}`);activeHash=location.hash;render(true);$('#guided-step-heading').scrollIntoView({block:'start',behavior:'instant'});$('#guided-step-title').focus({preventScroll:true})}
function guidedText(c){return [c.title,c.brief,`Evidência: ${c.evidence.kind}. ${c.evidence.summary}`,c.evidence.limits,'Premissas hipotéticas:',...c.assumptions.map(a=>`${a.label}: ${a.value}. ${a.why}`),'Invariantes:',...c.invariants,...c.steps.flatMap(s=>[`\n${guidedRange(s)} — ${s.title}`,`ENTREVISTADOR: ${s.interviewer}`,...s.candidate.map(p=>`VOCÊ: ${p}`),'DESENHE:',...s.draw,...s.mechanics.map(m=>`${m.title}: ${m.body}`),s.artifact.title,s.artifact.code,`INTERRUPÇÃO: ${s.challenge.question}`,s.challenge.answer,`ADAPTAÇÃO: ${s.challenge.pivot}`,`ESCOLHA: ${s.decision.choice}`,`ALTERNATIVA: ${s.decision.alternative}`,`POR QUÊ: ${s.decision.why}`,`MUDO SE: ${s.decision.whenToChange}`,`PRINCIPAL: ${s.principal}`,`CHECKPOINT: ${s.checkpoint}`]),'\nENCERRAMENTO',c.closing,'\nFONTES',...c.sourceIds.map(id=>sourceMap[id]).filter(Boolean).map(s=>`${s.title}: ${s.url||'material fornecido'}`)].join('\n\n')}
function bindGuided(){if(currentRoute!=='guided')return;$$('[data-guided-step]').forEach(b=>{b.onclick=()=>guidedMove(+b.dataset.guidedStep);b.onkeydown=ev=>{if(ev.key==='ArrowRight'||ev.key==='ArrowLeft'){ev.preventDefault();guidedMove(+b.dataset.guidedStep+(ev.key==='ArrowRight'?1:-1))}}});$('#guided-prev').onclick=()=>guidedMove(guidedStep-1);$('#guided-next').onclick=()=>guidedMove(guidedStep+1);$('#guided-rehearse').onchange=()=>{guidedRehearse=$('#guided-rehearse').checked;guidedRevealed=false;guidedFinal=false;history.replaceState(null,'',`#guided/${guidedCase().id}?step=${guidedStep+1}${guidedRehearse?'&mode=rehearse':''}`);activeHash=location.hash;render(true)};if($('#guided-reveal'))$('#guided-reveal').onclick=()=>{guidedRevealed=true;render(true);$('#guided-step-heading').scrollIntoView({block:'start',behavior:'instant'});$('#guided-step-title').focus({preventScroll:true})};$('#guided-final').onclick=()=>{guidedFinal=!guidedFinal;render(true)};$('#guided-motion').onclick=()=>{const board=$('.guided-board');board.classList.toggle('paused');$('#guided-motion').textContent=board.classList.contains('paused')?'Animar fluxo':'Pausar fluxo'};$$('[data-guided-node]').forEach(n=>{const inspect=()=>{const node=guidedCase().nodes.find(x=>x.id===n.dataset.guidedNode);$('#guided-node-detail').innerHTML=`<strong>${e(node.label)}</strong><p>${e(node.detail)}</p>`;$$('[data-guided-node]').forEach(el=>el.classList.toggle('selected',el===n))};n.onclick=inspect;n.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();inspect()}}});$$('[data-guided-edge],[data-guided-flow]').forEach(el=>{const inspect=()=>{const n=Number(el.dataset.guidedEdge??el.dataset.guidedFlow),c=guidedCase(),a=c.edges[n],f=c.nodes.find(x=>x.id===a.from),t=c.nodes.find(x=>x.id===a.to);$$('[data-guided-edge]').forEach(x=>x.classList.toggle('selected',Number(x.dataset.guidedEdge)===n));$('#guided-node-detail').innerHTML=`<strong>Fluxo ${n+1} · ${e(a.label)}</strong><p>${e(f.label)} → ${e(t.label)}</p><small>${e(t.detail)}</small>`;};el.onclick=inspect;if(el.hasAttribute('data-guided-edge'))el.onkeydown=ev=>{if(ev.key==='Enter'||ev.key===' '){ev.preventDefault();inspect()}};});$('#guided-complete').onclick=()=>{const ok=toggle(progress.checks,`guided:${guidedCase().id}:step:${guidedStep}`),done=progress.checks.includes(`guided:${guidedCase().id}:step:${guidedStep}`);$('#guided-complete').textContent=done?'✓ Etapa praticada':'Marcar etapa praticada';$('#guided-complete').setAttribute('aria-pressed',String(done));$('.guided-cases').innerHTML=D.guided.cases.map(guidedCard).join('');if(ok)toast('Etapa registrada no seu progresso')};$('#guided-download').onclick=()=>{const c=guidedCase(),url=URL.createObjectURL(new Blob([guidedText(c)],{type:'text/plain;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`nuarch-entrevista-${c.id}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}}


for(const [id,cls,key] of [['reading-mode','reading-mode','nuarch-reading-mode'],['font-size','large-type','nuarch-large-type']]){try{document.body.classList.toggle(cls,localStorage.getItem(key)==='true')}catch{}const control=$(`#${id}`);control.setAttribute('aria-pressed',String(document.body.classList.contains(cls)));control.onclick=()=>{document.body.classList.toggle(cls);const enabled=document.body.classList.contains(cls);control.setAttribute('aria-pressed',String(enabled));try{localStorage.setItem(key,String(enabled))}catch{}};}
init();
